#[derive(Debug, Clone)]
pub struct SourceScanResult {
    pub source: SnapshotSource,
    pub backfill_window_days: u64,
    pub backfill_file_limit: usize,
    pub discovered_file_count: usize,
    pub skipped_file_count_due_to_limit: usize,
    pub scan_cap_hit: bool,
    pub scanned_file_count: usize,
    pub scanned_session_count: usize,
    pub semantic_noop_count: usize,
    pub census_complete: bool,
    pub census_window_end: String,
    /// State-only Codex census is separate from transcript discovery. If an
    /// existing SQLite source was unreadable, its previous durable map must be
    /// retained even while healthy transcript siblings progress.
    pub state_census_complete: bool,
    /// Display/naming sidecars are optional enrichment, but a partial read
    /// cannot publish a source-wide manifest or advance the upload context.
    pub sidecar_census_complete: bool,
    pub symlink_rejected_count: usize,
    pub directory_entry_cap_exceeded_count: usize,
    pub unreadable_path_count: usize,
    pub oversized_file_count: usize,
    pub disappeared_file_count: usize,
    pub malformed_json_line_count: usize,
    pub invalid_utf8_line_count: usize,
    pub over_line_cap_count: usize,
    pub recognized_usage_drop_count: usize,
    pub ownership_incomplete_file_count: usize,
    pub zero_snapshot_confirmed_count: usize,
    pub zero_snapshot_usage_evidence_count: usize,
    pub dropped_usage_record_count: u64,
    /// The generation's SETTLED share of each public loss counter above
    /// (`ScanTraversalCounts::terminal_*`): loss that carries a durable
    /// terminal disposition or was settled as non-progressing once discovery
    /// finished without a retryable problem. Each is a decomposition of the
    /// public counter it is named after, never an addend, so `terminal <=
    /// public` always holds; equality in every class is what lets a receipt
    /// prove that all the loss it discloses is loss no retry can change.
    pub terminal_ownership_incomplete_file_count: usize,
    pub terminal_zero_snapshot_usage_evidence_count: usize,
    pub terminal_recognized_usage_drop_count: usize,
    pub terminal_dropped_usage_record_count: u64,
    pub terminal_over_line_cap_count: usize,
    /// Cardinalities of the residue witness this generation recorded
    /// (`ScanIndex::scan_residue_witness`), counts only. All zero when the
    /// generation did not complete (the durable witness then describes an
    /// earlier census, not this scan) and when it completed clean.
    pub census_residue_index_key_count: usize,
    pub census_residue_archived_rollout_count: usize,
    pub census_residue_blocked_session_count: usize,
    pub snapshots: Vec<SnapshotItem>,
    pending_finalization: Vec<PendingIndexFinalization>,
    pub(crate) local_codex_diagnostics: Option<CodexScanDiagnostics>,
    /// Local-only V2 counting receipts of this scan, moved out of its census.
    /// `None` when no configured counting parse finished (never a zero block).
    pub(crate) codex_counting_v2: Option<Box<crate::codex_scan_diagnostics::CountingV2Receipts>>,
    codex_join_validation: Option<codex_file_join::Validation>,
    codex_legacy_join_baselines: Vec<codex_file_join::LegacyBaseline>,
    /// Slice D1 shadow, measured by a complete Claude terminal scan before
    /// any fold. Count-only; the usage fold copies it into its counters.
    pub(crate) claude_request_census_shadow: Option<ClaudeRequestCensusShadowCounts>,
}
#[derive(Clone, Debug)]
pub(crate) struct CodexJoinValidator(codex_file_join::Validation);
impl CodexJoinValidator {
    pub(crate) fn validate(&self, snapshots: &[SnapshotItem]) -> Result<()> {
        let owners = snapshots
            .iter()
            .map(|item| resolve_codex_identity(&item.source_session_id))
            .collect();
        self.0.validate(&owners).map(|_| ())
    }
}
impl SourceScanResult {
    pub(crate) fn validate_codex_checkpoint(&self) -> Result<()> {
        if let Some(validation) = &self.codex_join_validation {
            validation.validate_all()?;
        }
        Ok(())
    }
    pub(crate) fn reconcile_codex_legacy_joining(
        &mut self,
        index: &mut ScanIndex,
        previous: &ScanIndex,
        machine_id: &str,
        mut project: impl FnMut(&mut ScanIndex, &mut Vec<SnapshotItem>),
    ) {
        let mut held = BTreeSet::new();
        for mut baseline in std::mem::take(&mut self.codex_legacy_join_baselines) {
            project(index, &mut baseline.snapshots);
            let matches = |snapshots: &[SnapshotItem]| {
                let fingerprints = snapshots
                    .iter()
                    .map(|snapshot| snapshot_fingerprint(SnapshotSource::Codex, snapshot))
                    .collect::<BTreeSet<_>>();
                let mut digest = Sha256::new();
                update_length_prefixed(&mut digest, b"snapshot_file_entity_set:v1");
                for fingerprint in fingerprints {
                    update_length_prefixed(&mut digest, fingerprint.as_bytes());
                }
                format!("{:x}", digest.finalize()) == baseline.expected
            };
            if matches(&baseline.snapshots) {
                continue;
            }
            // Explicit missing/conflict creator evidence intentionally retracts
            // legacy guessed ownership. Compare with the previously cached
            // binding only to isolate that authorized correction; never emit it.
            for item in &mut baseline.snapshots {
                if item
                    .session_account_evidence
                    .as_ref()
                    .is_some_and(|evidence| {
                        evidence.evidence_source == "codex_creator_header:v1"
                            && matches!(evidence.identity_disposition, Some("missing" | "conflict"))
                    })
                {
                    let key =
                        sha256_hex(&["session_owner:v1", machine_id, &item.source_session_id]);
                    if let Some(binding) = previous.session_account_bindings.get(&key) {
                        set_session_account_hash(item, Some(&binding.account_identifier_hash));
                    }
                }
            }
            if !matches(&baseline.snapshots) {
                held.insert(baseline.owner);
            }
        }
        if held.is_empty() {
            if self.census_complete
                && !self.pending_finalization.iter().any(|pending| {
                    index
                        .files
                        .get(&pending.index_key)
                        .is_some_and(|entry| entry.codex_applied_tier_receipt.is_some())
                })
            {
                index.traversal = None;
                index.resume_after_path = None;
                index.resume_upper_bound_path = None;
                index.resume_census_window_end = None;
            }
            return;
        }
        self.hold_codex_groups(
            index,
            previous,
            &held,
            "legacy applied output could not be reproduced",
        );
    }
    pub(crate) fn hold_codex_groups(
        &mut self,
        index: &mut ScanIndex,
        previous: &ScanIndex,
        held: &BTreeSet<String>,
        reason: &str,
    ) {
        if held.is_empty() {
            return;
        }
        self.census_complete = false;
        self.scan_cap_hit = true;
        if let Some(diagnostic) = self.local_codex_diagnostics.as_mut() {
            diagnostic.gates.census_complete = false;
            diagnostic.gates.traversal_healthy = false;
        }
        let sources = self
            .snapshots
            .iter()
            .filter(|snapshot| held.contains(&resolve_codex_identity(&snapshot.source_session_id)))
            .filter_map(|snapshot| snapshot.source_file_fingerprint.as_ref())
            .collect::<BTreeSet<_>>();
        let mut keys = index
            .files
            .iter()
            .filter(|(_, entry)| sources.contains(&entry.source_file_fingerprint))
            .map(|(key, _)| key.clone())
            .collect::<BTreeSet<_>>();
        if let Some(validation) = &self.codex_join_validation {
            keys.extend(
                validation
                    .groups
                    .iter()
                    .filter(|group| held.contains(&group.owner))
                    .flat_map(|group| {
                        group
                            .members
                            .iter()
                            .map(|member| local_index_key(&member.path))
                    }),
            );
        }
        self.ownership_incomplete_file_count += keys.len();
        for key in &keys {
            index.remove_file_entry(key);
            if let Some(entry) = previous.files.get(key) {
                index.files.insert(key.clone(), entry.clone());
            }
            if let Some(fingerprints) = previous.file_snapshot_fingerprints.get(key) {
                index
                    .file_snapshot_fingerprints
                    .insert(key.clone(), fingerprints.clone());
            }
            if previous.confirmed_empty_files.contains(key) {
                index.confirmed_empty_files.insert(key.clone());
            }
            index.revert_codex_blocked_attribution(previous, key);
        }
        self.pending_finalization
            .retain(|pending| !keys.contains(&pending.index_key));
        self.snapshots.retain(|snapshot| {
            !held.contains(&resolve_codex_identity(&snapshot.source_session_id))
        });
        if let Some(traversal) = index.traversal.as_mut() {
            traversal.counts.ownership_incomplete_file_count += keys.len();
            traversal
                .counts
                .record_unreadable(UnreadableCause::LegacyHold, 1);
            traversal.residue.index_keys.extend(keys);
            traversal
                .residue
                .blocked_session_ids
                .extend(held.iter().cloned());
            let now = rfc3339_unix_seconds(&self.census_window_end).unwrap_or_default();
            traversal.unhealthy_retry_attempt = traversal
                .unhealthy_retry_attempt
                .saturating_add(1)
                .min(UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS);
            traversal.unhealthy_retry_not_before_unix_seconds = Some(now.saturating_add(
                unhealthy_scan_retry_delay_seconds(traversal.unhealthy_retry_attempt),
            ));
        }
        index
            .codex_state_only_blocked_session_ids
            .extend(held.iter().cloned());
        index
            .codex_state_only_blocked_unattributed
            .extend(held.iter().cloned());
        if let Some(validation) = &mut self.codex_join_validation {
            validation
                .groups
                .retain(|group| !held.contains(&group.owner));
        }
        index.scan_residue_witness = previous.scan_residue_witness.clone();
        eprintln!(
            "ottto-service: held {} Codex file group(s): {reason}",
            held.len()
        );
    }
    pub(crate) fn finish_codex_capture_boundary(&self, index: &mut ScanIndex) {
        if self.census_complete {
            index.traversal = None;
            index.resume_after_path = None;
            index.resume_upper_bound_path = None;
            index.resume_census_window_end = None;
        }
    }
    /// Index keys this scan read to completion, with their parsed source
    /// fingerprints.
    pub(crate) fn completed_parses(&self) -> impl Iterator<Item = (&str, &str)> {
        self.pending_finalization
            .iter()
            .filter(|pending| pending.parse_complete)
            .map(|pending| {
                (
                    pending.index_key.as_str(),
                    pending.source_file_fingerprint.as_str(),
                )
            })
    }
    pub(crate) fn codex_joining_validator(&self) -> Option<CodexJoinValidator> {
        self.codex_join_validation.clone().map(CodexJoinValidator)
    }
}

#[derive(Debug, Clone)]
struct PendingIndexFinalization {
    sampled_audit_verified: bool,
    codex_pending_recovery: bool,
    index_key: String,
    source_file_fingerprint: String,
    previous_snapshot_fingerprint: Option<String>,
    previous_upload_body_witness: Option<String>,
    parse_complete: bool,
    diagnostic_reason: FileReason,
    parsed_snapshot_count: usize,
    effective_upload_body_witness_revision: u64,
}

#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
pub struct SnapshotUploadPolicy {
    pub session_titles_enabled: bool,
    pub workspace_labels_enabled: bool,
    pub session_artifacts_enabled: bool,
    pub session_attribution_enabled: bool,
    /// Backend capability derived from the existing session-title privacy
    /// choice. It is not a separate user setting and defaults off for older
    /// backends that do not advertise the additive private-label contract.
    pub session_attribution_labels_enabled: bool,
}

pub(crate) fn snapshot_source_from_api_slug(value: &str) -> Option<SnapshotSource> {
    match value {
        "codex" => Some(SnapshotSource::Codex),
        "claude_code" => Some(SnapshotSource::ClaudeCode),
        "pi" => Some(SnapshotSource::Pi),
        _ => None,
    }
}

impl Default for SnapshotUploadPolicy {
    fn default() -> Self {
        Self {
            session_titles_enabled: true,
            workspace_labels_enabled: true,
            // Opt-in: artifacts are stripped before upload unless the backend
            // activity hint explicitly enables them for the org.
            session_artifacts_enabled: false,
            // Opt-in: compact facts stay local unless the backend explicitly
            // enables the additive attribution contract.
            session_attribution_enabled: false,
            session_attribution_labels_enabled: false,
        }
    }
}

pub fn apply_upload_policy(
    source: SnapshotSource,
    snapshots: &mut [SnapshotItem],
    policy: SnapshotUploadPolicy,
) {
    for item in snapshots {
        let mut fingerprint_needs_refresh = false;
        if !policy.session_titles_enabled
            && (item.session_display_name.is_some() || item.session_display_name_source.is_some())
        {
            item.session_display_name = None;
            item.session_display_name_source = None;
            fingerprint_needs_refresh = true;
        }
        if !policy.workspace_labels_enabled
            && (item.workspace_display_label.is_some()
                || item.workspace_label_source.is_some()
                || item.repository_label.is_some()
                || item.repository_label_source.is_some())
        {
            item.workspace_display_label = None;
            item.workspace_label_source = None;
            item.repository_label = None;
            item.repository_label_source = None;
            fingerprint_needs_refresh = true;
        }
        if !policy.session_artifacts_enabled && !item.session_artifacts.is_empty() {
            item.session_artifacts.clear();
            fingerprint_needs_refresh = true;
        }
        if !policy.session_attribution_enabled && !item.attribution_facts.is_empty() {
            item.attribution_facts.clear();
            fingerprint_needs_refresh = true;
        } else if (!policy.session_titles_enabled || !policy.session_attribution_labels_enabled)
            && crate::session_attribution::strip_display_labels(&mut item.attribution_facts)
        {
            fingerprint_needs_refresh = true;
        }
        if !policy.session_attribution_labels_enabled {
            if let Some(summary) = item.activity_summary.as_mut() {
                if !summary.skills.is_empty() {
                    summary.skills.clear();
                    fingerprint_needs_refresh = true;
                }
            }
        }
        if let Some(start) = item.session_start.as_mut() {
            // Outside the fingerprint: consent changes only which identity an
            // opening file carries, never the session's content.
            start.apply_upload_policy(
                policy.workspace_labels_enabled,
                policy.session_attribution_enabled,
            );
        }
        if fingerprint_needs_refresh {
            item.snapshot_fingerprint = snapshot_fingerprint(source, item);
        }
        fit_context_curve_to_snapshot_item_budget(
            source,
            item,
            policy,
            MAX_SNAPSHOT_ITEM_WIRE_BYTES,
        );
    }
}

fn snapshot_item_wire_size(
    source: SnapshotSource,
    item: &SnapshotItem,
    policy: SnapshotUploadPolicy,
) -> usize {
    serde_json::to_vec(&SnapshotItemWire {
        snapshot: item,
        semantic_envelope: snapshot_semantic_envelope(source, item, policy),
    })
    .map(|encoded| encoded.len())
    .unwrap_or(usize::MAX)
}

fn fit_context_curve_to_snapshot_item_budget(
    source: SnapshotSource,
    item: &mut SnapshotItem,
    policy: SnapshotUploadPolicy,
    item_wire_budget: usize,
) {
    if item.context_curve.is_none()
        || snapshot_item_wire_size(source, item, policy) <= item_wire_budget
    {
        return;
    }
    while item
        .context_curve
        .as_mut()
        .is_some_and(prune_one_context_curve_fill_point)
    {
        if snapshot_item_wire_size(source, item, policy) <= item_wire_budget {
            return;
        }
    }
    let Some(curve) = item.context_curve.as_ref() else {
        return;
    };
    item.context_curve = Some(unavailable_context_curve(
        &curve.parser_revision,
        &curve.ownership_revision,
        "payload_budget_exceeded",
        0,
        0,
    ));
}

fn snapshot_item_wire_size_is_allowed(
    item_size: usize,
    item_without_curve_size: usize,
    context_curve_coverage: Option<&str>,
) -> bool {
    item_size <= MAX_SNAPSHOT_ITEM_WIRE_BYTES
        || (context_curve_coverage == Some("payload_budget_exceeded")
            && item_without_curve_size <= MAX_SNAPSHOT_ITEM_WIRE_BYTES
            && item_size <= MAX_SNAPSHOT_ITEM_CLEAR_WIRE_BYTES)
}

/// Bind incremental state to the exact bytes/semantics that will go on the
/// wire. This MUST run after every enrichment, privacy policy, and account
/// cutoff. Parser-time fingerprints are provisional only: committing them
/// earlier can suppress a later policy/enrichment correction forever.
pub fn finalize_scan_after_policy(
    source: SnapshotSource,
    result: &mut SourceScanResult,
    index: &mut ScanIndex,
) {
    finalize_scan_after_policy_with_body_witness(
        source,
        result,
        index,
        snapshot_upload_body_witness,
    );
}

/// Sample existing quarantine metadata only. These are working-index witnesses
/// at finalization, not a claim about later partial-checkpoint persistence.
pub(crate) fn prepare_codex_recovery_diagnostics(
    result: &mut SourceScanResult,
    index: &ScanIndex,
    quarantines: &BTreeMap<String, SnapshotQuarantineRecord>,
) {
    let Some(diagnostic) = result.local_codex_diagnostics.as_mut() else {
        return;
    };
    diagnostic.lineage = [None; LINEAGE_SAMPLES];
    diagnostic.sample_offset = 0;
    diagnostic.quarantine_count = quarantines.len() as u64;
    if quarantines.is_empty() {
        return;
    }
    let offset = (diagnostic.generation % quarantines.len() as u64) as usize;
    diagnostic.sample_offset = offset as u64;
    for (slot, (fingerprint, quarantine)) in quarantines
        .iter()
        .cycle()
        .skip(offset)
        .take(quarantines.len().min(LINEAGE_SAMPLES))
        .enumerate()
    {
        let mut sample = RecoveryLineage::new(fingerprint, quarantine.disposition);
        for (key, fingerprints) in &index.file_snapshot_fingerprints {
            if fingerprints.contains(fingerprint) {
                sample.before_current = true;
                sample.associated_file_count = sample.associated_file_count.saturating_add(1);
                if sample.file_key_digest.is_none() {
                    sample.file_key_digest = Some(codex_scan_diagnostics::digest(key));
                    sample.previous_body_digest = result
                        .pending_finalization
                        .iter()
                        .find(|pending| &pending.index_key == key)
                        .and_then(|pending| pending.previous_upload_body_witness.as_deref())
                        .or_else(|| {
                            index
                                .files
                                .get(key)
                                .and_then(|entry| entry.last_upload_body_witness.as_deref())
                        })
                        .map(codex_scan_diagnostics::digest);
                }
            }
        }
        // Preserve the canonical current-set fallback for pre-entity-map indexes.
        for (key, entry) in &index.files {
            if !index.file_snapshot_fingerprints.contains_key(key)
                && entry.last_snapshot_fingerprint.as_ref() == Some(fingerprint)
            {
                sample.before_current = true;
                sample.associated_file_count = sample.associated_file_count.saturating_add(1);
                if sample.file_key_digest.is_none() {
                    sample.file_key_digest = Some(codex_scan_diagnostics::digest(key));
                    sample.legacy_file_association = true;
                    sample.previous_body_digest = entry
                        .last_upload_body_witness
                        .as_deref()
                        .map(codex_scan_diagnostics::digest);
                }
            }
        }
        sample.before_current |= index
            .codex_state_only_snapshot_fingerprints
            .values()
            .any(|current| current == fingerprint);
        diagnostic.lineage[slot] = Some(sample);
    }
}

/// Finalize using the additive body witness of the effective upload projection.
/// The witness function sees recomputed semantic fingerprints and must return
/// a stable witness for both file no-op suppression and quarantine retries.
/// It does not modify the local snapshot items or semantic entity identity.
pub fn finalize_scan_after_policy_with_body_witness(
    source: SnapshotSource,
    result: &mut SourceScanResult,
    index: &mut ScanIndex,
    mut body_witness: impl FnMut(&SnapshotItem) -> String,
) {
    for snapshot in &mut result.snapshots {
        snapshot.snapshot_fingerprint = snapshot_fingerprint(source, snapshot);
        index.snapshot_activity_at.insert(
            snapshot.snapshot_fingerprint.clone(),
            snapshot_semantic_activity_at(snapshot),
        );
    }

    let mut by_source_file: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut by_source_file_body_witness: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    for snapshot in &result.snapshots {
        if let Some(source_file_fingerprint) = snapshot.source_file_fingerprint.as_ref() {
            by_source_file
                .entry(source_file_fingerprint.clone())
                .or_default()
                .insert(snapshot.snapshot_fingerprint.clone());
            by_source_file_body_witness
                .entry(source_file_fingerprint.clone())
                .or_default()
                .insert(body_witness(snapshot));
        }
    }

    let mut noop_source_files = BTreeSet::new();
    for pending in &result.pending_finalization {
        if let Some(diagnostic) = result.local_codex_diagnostics.as_mut() {
            let key_digest = codex_scan_diagnostics::digest(&pending.index_key);
            for sample in diagnostic.lineage.iter_mut().flatten() {
                if sample.file_key_digest == Some(key_digest) {
                    sample.file_reason = pending.diagnostic_reason;
                    sample.parsed_count = pending.parsed_snapshot_count as u64;
                }
            }
        }
        if !pending.parse_complete {
            continue;
        }
        let final_fingerprints = by_source_file
            .get(&pending.source_file_fingerprint)
            .cloned()
            .unwrap_or_default();
        let final_group_fingerprint = (!final_fingerprints.is_empty()).then(|| {
            let mut digest = Sha256::new();
            update_length_prefixed(&mut digest, b"snapshot_file_entity_set:v1");
            for fingerprint in &final_fingerprints {
                update_length_prefixed(&mut digest, fingerprint.as_bytes());
            }
            format!("{:x}", digest.finalize())
        });
        let final_upload_body_witness = by_source_file_body_witness
            .get(&pending.source_file_fingerprint)
            .filter(|witnesses| !witnesses.is_empty())
            .map(|witnesses| {
                let mut digest = Sha256::new();
                update_length_prefixed(&mut digest, b"snapshot_file_upload_body_set:v1");
                for witness in witnesses {
                    update_length_prefixed(&mut digest, witness.as_bytes());
                }
                format!("{:x}", digest.finalize())
            });
        if pending.sampled_audit_verified {
            crate::local_resource_diagnostics::sampled_audit_comparison(
                source.api_slug(),
                (
                    final_group_fingerprint.as_deref(),
                    pending.previous_snapshot_fingerprint.as_deref(),
                ),
                (
                    final_upload_body_witness.as_deref(),
                    pending.previous_upload_body_witness.as_deref(),
                ),
            );
        }
        let quarantine_retry_required = result.snapshots.iter().any(|snapshot| {
            snapshot.source_file_fingerprint.as_deref()
                == Some(pending.source_file_fingerprint.as_str())
                && index.quarantine_requires_retry_body(
                    &snapshot.snapshot_fingerprint,
                    &body_witness(snapshot),
                )
        });
        if let Some(entry) = index.files.get_mut(&pending.index_key) {
            entry.last_snapshot_fingerprint = final_group_fingerprint.clone();
            entry.last_upload_body_witness = final_upload_body_witness.clone();
            if pending.effective_upload_body_witness_revision != 0
                && !index
                    .effective_upload_body_witness_revision_excluded_source_files
                    .contains(&pending.source_file_fingerprint)
            {
                entry.effective_upload_body_witness_revision =
                    pending.effective_upload_body_witness_revision;
            }
        }
        if let Some(diagnostic) = result.local_codex_diagnostics.as_mut() {
            let key_digest = codex_scan_diagnostics::digest(&pending.index_key);
            for sample in diagnostic.lineage.iter_mut().flatten() {
                if sample.file_key_digest == Some(key_digest) {
                    sample.finalized = true;
                    sample.finalized_entity_count = final_fingerprints.len() as u64;
                    for (slot, fingerprint) in
                        final_fingerprints.iter().take(LINEAGE_SAMPLES).enumerate()
                    {
                        sample.successor_digests[slot] =
                            codex_scan_diagnostics::digest(fingerprint);
                    }
                    sample.final_body_digest = final_upload_body_witness
                        .as_deref()
                        .map(codex_scan_diagnostics::digest);
                    sample.final_body_revision = index
                        .files
                        .get(&pending.index_key)
                        .map(|entry| entry.effective_upload_body_witness_revision)
                        .unwrap_or_default();
                }
            }
        }
        if final_fingerprints.is_empty() {
            index.file_snapshot_fingerprints.remove(&pending.index_key);
            index
                .confirmed_empty_files
                .insert(pending.index_key.clone());
        } else {
            index
                .file_snapshot_fingerprints
                .insert(pending.index_key.clone(), final_fingerprints);
            index.confirmed_empty_files.remove(&pending.index_key);
        }
        if final_group_fingerprint.is_some()
            && final_group_fingerprint == pending.previous_snapshot_fingerprint
            && final_upload_body_witness == pending.previous_upload_body_witness
            // An unresolved POST may have replaced that older accepted body.
            // Use the pre-replay fact: record() writes provisional new entries.
            && !pending.codex_pending_recovery
            && !quarantine_retry_required
        {
            noop_source_files.insert(pending.source_file_fingerprint.clone());
            result.semantic_noop_count = result
                .semantic_noop_count
                .saturating_add(pending.parsed_snapshot_count);
        }
    }
    result.snapshots.retain(|snapshot| {
        snapshot
            .source_file_fingerprint
            .as_ref()
            .map(|source_file| !noop_source_files.contains(source_file))
            .unwrap_or(true)
    });

    // State-only Codex entities do not have a source-file fingerprint, so they
    // cannot use the file finalization table above. Rebind their durable map to
    // the final post-enrichment/post-policy/post-cutoff fingerprint here. This
    // is also where no-op suppression belongs: parser-time equality is not
    // authoritative when a privacy policy or account cutoff changed.
    if source == SnapshotSource::Codex && result.state_census_complete {
        let previous = index.codex_state_only_snapshot_fingerprints.clone();
        let mut current = BTreeMap::new();
        let mut noop_state_only = BTreeSet::new();
        for snapshot in &result.snapshots {
            if snapshot.source_file_fingerprint.is_none()
                && snapshot.provenance.collector == "codex_state_sqlite"
            {
                let fingerprint = snapshot.snapshot_fingerprint.clone();
                if previous.get(&snapshot.source_session_id) == Some(&fingerprint)
                    && index.snapshot_activity_at.contains_key(&fingerprint)
                    && !index.quarantine_requires_retry(&fingerprint)
                {
                    noop_state_only.insert(snapshot.source_session_id.clone());
                    result.semantic_noop_count = result.semantic_noop_count.saturating_add(1);
                }
                current.insert(snapshot.source_session_id.clone(), fingerprint);
            }
        }
        index.codex_state_only_snapshot_fingerprints = current;
        result.snapshots.retain(|snapshot| {
            snapshot.source_file_fingerprint.is_some()
                || snapshot.provenance.collector != "codex_state_sqlite"
                || !noop_state_only.contains(&snapshot.source_session_id)
        });
    }
    if result.census_complete {
        if !index.bounded_sweep_had_unsettled_upload {
            index.upload_context_fingerprint = index.active_upload_context_fingerprint.clone();
        }
        index.bounded_sweep_had_unsettled_upload = false;
    }
    let current_fingerprints = index
        .file_snapshot_fingerprints
        .values()
        .flat_map(BTreeSet::iter)
        .chain(index.codex_state_only_snapshot_fingerprints.values())
        .collect::<BTreeSet<_>>();
    index
        .snapshot_activity_at
        .retain(|fingerprint, _| current_fingerprints.contains(fingerprint));
}

/// The producer-side event clock mirrored by the accepted-log append path.
/// The maximum activity clock is stable across retries and reconstructible on
/// both sides. `collected_at` is deliberately excluded because it is an
/// observation clock; metadata-only entities without semantic activity do not
/// participate in a v2 manifest.
fn snapshot_semantic_activity_at(item: &SnapshotItem) -> Option<String> {
    item.usage_buckets
        .iter()
        .flat_map(|bucket| {
            [
                Some(bucket.bucket_start.as_str()),
                bucket.first_activity_at.as_deref(),
                bucket.last_activity_at.as_deref(),
            ]
        })
        .chain([
            item.source_started_at.as_deref(),
            item.source_ended_at.as_deref(),
            item.source_last_activity_at.as_deref(),
        ])
        .flatten()
        .filter_map(|value| {
            OffsetDateTime::parse(value, &Rfc3339)
                .ok()
                .map(|parsed| (parsed, value))
        })
        .max_by_key(|(parsed, _)| *parsed)
        .map(|(_, value)| value.to_string())
}

/// Reasoning-effort tiers Claude Code reports today. Kept in one place so the
/// transcript reader and the OTLP sidecar admit exactly the same vocabulary.
const CLAUDE_EFFORT_TIERS: &[&str] = &["low", "medium", "high", "xhigh", "max"];

/// The applied reasoning-effort tier recorded on this transcript record.
///
/// Claude Code writes it as a top-level `effort` field on assistant records.
/// Unknown or malformed values degrade to `None` (effort-unknown) rather than
/// inventing a tier, and the vocabulary check keeps a future Claude tier from
/// silently widening the column the backend stores this in.
fn claude_transcript_effort(value: &Value) -> Option<String> {
    let effort = string_at(value, &["effort"])?.trim().to_ascii_lowercase();
    CLAUDE_EFFORT_TIERS
        .contains(&effort.as_str())
        .then_some(effort)
}

/// Apply privacy-safe account identity reduced from Claude Code's local OTLP.
///
/// Reasoning effort comes only from each assistant transcript record. Local
/// OTLP evidence may stamp an exactly covered session or proven account family,
/// but it must never supply or split reasoning-effort tiers.
pub fn apply_claude_effort_evidence(
    snapshots: &mut [SnapshotItem],
    evidence_by_session: &BTreeMap<String, Vec<crate::claude_local_otel::ClaudeLocalOtelEvidence>>,
) {
    let mut witnesses = BTreeMap::new();
    apply_claude_effort_evidence_with_families(
        snapshots,
        evidence_by_session,
        &mut witnesses,
        &BTreeMap::new(),
    );
}

pub fn apply_claude_effort_evidence_with_index(
    snapshots: &mut [SnapshotItem],
    evidence_by_session: &BTreeMap<String, Vec<crate::claude_local_otel::ClaudeLocalOtelEvidence>>,
    index: &mut ScanIndex,
    census_complete: bool,
    census_window_end: &str,
) {
    let complete_family_members = if census_complete {
        complete_claude_family_members(index)
    } else {
        BTreeMap::new()
    };
    if census_complete {
        // v29 witnesses predate per-member request-set fingerprints. Removing
        // one without revisiting its unchanged transcript files would strand
        // later child-only reparses: scan identity stays at v24, so no ordinary
        // parser upgrade selects those files. Schedule only the affected
        // complete families for a bounded local reparse before the legacy
        // witness is discarded. The old count-only witness is never used to
        // stamp a v30 parse; the reparse must rebuild exact request coverage.
        let legacy_witness_roots = index
            .claude_account_family_witnesses
            .iter()
            .filter_map(|(root_session_id, witness)| {
                let fingerprint_members = witness
                    .member_request_id_fingerprints
                    .keys()
                    .cloned()
                    .collect::<BTreeSet<_>>();
                let witness_members = witness.members.keys().cloned().collect::<BTreeSet<_>>();
                (fingerprint_members != witness_members
                    && complete_family_members.contains_key(root_session_id))
                .then_some(root_session_id.clone())
            })
            .collect::<BTreeSet<_>>();
        for (index_key, entry) in &mut index.files {
            let Some((root_session_id, source_session_id)) =
                claude_index_path_family_member(Path::new(index_key))
            else {
                continue;
            };
            if legacy_witness_roots.contains(&root_session_id)
                && complete_family_members
                    .get(&root_session_id)
                    .is_some_and(|members| members.contains(&source_session_id))
            {
                entry.source_file_fingerprint.clear();
            }
        }
        index
            .claude_account_family_witnesses
            .retain(|root_session_id, witness| {
                complete_family_members
                    .get(root_session_id)
                    .is_some_and(|members| {
                        members == &witness.members.keys().cloned().collect::<BTreeSet<_>>()
                            && members
                                == &witness
                                    .member_request_id_fingerprints
                                    .keys()
                                    .cloned()
                                    .collect::<BTreeSet<_>>()
                    })
            });
    }
    accumulate_claude_family_pending(
        snapshots,
        evidence_by_session,
        &mut index.claude_account_family_pending,
        census_window_end,
    );
    let proven_families = if census_complete {
        complete_family_members
            .iter()
            .filter_map(|(root_session_id, complete_members)| {
                index
                    .claude_account_family_pending
                    .get(root_session_id)
                    .filter(|pending| {
                        !pending.invalid
                            && pending.census_window_end == census_window_end
                            && &pending.members.keys().cloned().collect::<BTreeSet<_>>()
                                == complete_members
                            && &pending
                                .member_request_id_hashes
                                .keys()
                                .cloned()
                                .collect::<BTreeSet<_>>()
                                == complete_members
                            && claude_family_request_ids_are_disjoint(pending)
                    })
                    .map(|pending| {
                        (
                            root_session_id.clone(),
                            ProvenClaudeAccountFamily {
                                members: pending.members.clone(),
                                member_request_id_fingerprints: pending
                                    .member_request_id_hashes
                                    .iter()
                                    .map(|(source_session_id, request_id_hashes)| {
                                        (
                                            source_session_id.clone(),
                                            claude_request_id_set_fingerprint(request_id_hashes),
                                        )
                                    })
                                    .collect(),
                            },
                        )
                    })
            })
            .collect::<BTreeMap<_, _>>()
    } else {
        BTreeMap::new()
    };
    let witness_roots_before = index
        .claude_account_family_witnesses
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    apply_claude_effort_evidence_with_families(
        snapshots,
        evidence_by_session,
        &mut index.claude_account_family_witnesses,
        &proven_families,
    );
    if census_complete {
        index.claude_account_family_pending.clear();
        let current_source_session_ids = snapshots
            .iter()
            .map(|snapshot| snapshot.source_session_id.as_str())
            .collect::<BTreeSet<_>>();
        let newly_proven_roots = proven_families
            .keys()
            .filter(|root_session_id| {
                !witness_roots_before.contains(*root_session_id)
                    && index
                        .claude_account_family_witnesses
                        .contains_key(*root_session_id)
            })
            .collect::<BTreeSet<_>>();
        for (index_key, entry) in &mut index.files {
            let Some((root_session_id, source_session_id)) =
                claude_index_path_family_member(Path::new(index_key))
            else {
                continue;
            };
            if newly_proven_roots.contains(&root_session_id)
                && !current_source_session_ids.contains(source_session_id.as_str())
            {
                // Earlier pages uploaded an honest NULL before the terminal
                // census could prove the family. Reparse them once so the new
                // durable witness emits the correction on the next pass.
                entry.source_file_fingerprint.clear();
            }
        }
    }
}

pub fn claude_pending_family_session_ids(index: &ScanIndex) -> Vec<String> {
    index
        .claude_account_family_pending
        .keys()
        .chain(index.claude_usage_family_pending.keys())
        .chain(index.claude_usage_family_witnesses.keys())
        .chain(
            index
                .claude_usage_family_witnesses
                .values()
                .flat_map(|witness| witness.legacy_owner_roots.iter()),
        )
        .cloned()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

