    fn claude_authority_preflight_identity_fence_is_family_scoped() {
        let root = temp_dir("claude-authority-preflight-family-scope");
        let quarantined_root = "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee";
        let healthy_root = "11111111-2222-3333-4444-555555555555";
        let quarantined_path = root.join(format!("{quarantined_root}.jsonl"));
        let healthy_path = root.join(format!("{healthy_root}.jsonl"));
        fs::write(&quarantined_path, "{}\n").expect("write quarantined transcript");
        fs::write(&healthy_path, "{}\n").expect("write healthy transcript");

        let mut index = ScanIndex::default();
        index.claude_usage_authority_quarantine.insert(
            quarantined_root.to_string(),
            ClaudeUsageAuthorityQuarantineRecord {
                proof_correction: None,
                contract: CLAUDE_USAGE_AUTHORITY_QUARANTINE_CONTRACT_VERSION.to_string(),
                proven_witness_fingerprint: "witness".to_string(),
                member_source_file_fingerprints: BTreeMap::new(),
                failed_reconstruction_count: 1,
                disposition: ClaudeUsageAuthorityQuarantineDisposition::RetryPending,
                retry_after_unix_seconds: u64::MAX,
            },
        );
        let mut quarantined = test_candidate(quarantined_path);
        quarantined.source_file_fingerprint = "quarantined-revision".to_string();
        let mut healthy = test_candidate(healthy_path);
        healthy.source_file_fingerprint = "healthy-revision".to_string();

        assert_eq!(
            claude_authority_preflight_fingerprint(&index, &quarantined).as_deref(),
            Some("quarantined-revision"),
            "the family under reconstruction keeps the exact preflight fence"
        );
        assert_eq!(
            claude_authority_preflight_fingerprint(&index, &healthy),
            None,
            "an unrelated live session may advance before its authoritative parse open"
        );

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn claude_authority_family_evolution_reparses_every_quarantined_sibling() {
        let root_session_id = "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee";
        let root = temp_dir("claude-authority-family-evolution");
        let write_member = |agent_id: Option<&str>| {
            let path = match agent_id {
                Some(agent_id) => root
                    .join(root_session_id)
                    .join("subagents")
                    .join(format!("agent-{agent_id}.jsonl")),
                None => root.join(format!("{root_session_id}.jsonl")),
            };
            fs::create_dir_all(path.parent().expect("member parent"))
                .expect("create family directory");
            let request_id = agent_id.unwrap_or("root");
            fs::write(
                &path,
                format!(
                    "{}\n",
                    json!({
                        "timestamp": "2026-08-23T18:20:00Z",
                        "type": "assistant",
                        "sessionId": root_session_id,
                        "agentId": agent_id,
                        "isSidechain": agent_id.is_some(),
                        "requestId": format!("request-{request_id}"),
                        "message": {
                            "id": format!("message-{request_id}"),
                            "model": "claude-haiku-4-5",
                            "usage": {"input_tokens": 10, "output_tokens": 1}
                        }
                    })
                ),
            )
            .expect("write family member");
            path
        };
        write_member(None);
        let revised_member = write_member(Some("0000000000000001"));
        write_member(Some("0000000000000002"));

        let mut index = ScanIndex::default();
        let initial = scan_source_roots(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&root),
            &mut index,
            "2026-08-23T18:30:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("index initial family");
        assert_eq!(initial.scanned_file_count, 3);
        let members = index
            .files
            .iter()
            .filter_map(|(index_key, entry)| {
                let (family_root, member) = claude_index_path_family_member(Path::new(index_key))?;
                (family_root == root_session_id)
                    .then(|| (member, entry.source_file_fingerprint.clone()))
            })
            .collect::<BTreeMap<_, _>>();
        assert_eq!(members.len(), 3);
        let witness = ClaudeUsageFamilyWitness {
            evidence_fingerprint: "provider-evidence".to_string(),
            member_request_id_fingerprints: members
                .keys()
                .map(|member| (member.clone(), "requests".to_string()))
                .collect(),
            member_occurrence_fingerprints: members
                .keys()
                .map(|member| (member.clone(), "occurrences".to_string()))
                .collect(),
            assigned_request_id_fingerprints: members
                .keys()
                .map(|member| (member.clone(), "assigned".to_string()))
                .collect(),
            legacy_excluded_request_id_hashes: BTreeMap::new(),
            legacy_exclusion_evidence_fingerprint: None,
            legacy_owner_roots: BTreeSet::new(),
        };
        let witness_fingerprint = claude_usage_family_witness_fingerprint(&witness);
        index
            .claude_usage_family_witnesses
            .insert(root_session_id.to_string(), witness);
        index.claude_usage_authority_quarantine.insert(
            root_session_id.to_string(),
            ClaudeUsageAuthorityQuarantineRecord {
                proof_correction: None,
                contract: CLAUDE_USAGE_AUTHORITY_QUARANTINE_CONTRACT_VERSION.to_string(),
                proven_witness_fingerprint: witness_fingerprint,
                member_source_file_fingerprints: members,
                failed_reconstruction_count: 1,
                disposition: ClaudeUsageAuthorityQuarantineDisposition::RetryPending,
                retry_after_unix_seconds: u64::MAX,
            },
        );

        let unchanged = scan_source_roots(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&root),
            &mut index,
            "2026-08-23T18:31:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("scan unchanged quarantined family");
        assert_eq!(unchanged.scanned_file_count, 0);

        fs::OpenOptions::new()
            .append(true)
            .open(&revised_member)
            .and_then(|mut file| std::io::Write::write_all(&mut file, b"{}\n"))
            .expect("revise one family member");
        let revised = scan_source_roots_with_artifacts(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&root),
            &mut index,
            "2026-08-23T18:31:30Z",
            BACKFILL_WINDOW_DAYS,
            true,
        )
        .expect("scan revised quarantined family");
        assert_eq!(revised.scanned_file_count, 3);
        assert_eq!(
            revised.snapshots.len(),
            3,
            "one revision change reparses the changed member and every unchanged sibling"
        );

        write_member(Some("0000000000000003"));
        let evolved = scan_source_roots_with_artifacts(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&root),
            &mut index,
            "2026-08-23T18:32:00Z",
            BACKFILL_WINDOW_DAYS,
            true,
        )
        .expect("scan expanded quarantined family");
        assert_eq!(evolved.scanned_file_count, 4);
        assert_eq!(
            evolved.snapshots.len(),
            4,
            "one membership change reparses the new member and every unchanged sibling"
        );

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn legacy_scan_index_reparses_once_to_establish_semantic_activity_witness() {
        let root = temp_dir("scan-index-migration");
        let path = root.join("rollout-019e253c-6666-7000-9000-ffffffffffff.jsonl");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-07-22T08:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"019e253c-6666-7000-9000-ffffffffffff\"}}\n",
                "{\"timestamp\":\"2026-07-22T08:01:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":10,\"output_tokens\":2},\"model\":\"gpt-5.5\"}}}\n"
            ),
        )
        .expect("write fixture");
        let metadata = fs::metadata(&path).expect("metadata");
        let modified_unix_seconds = metadata
            .modified()
            .ok()
            .and_then(unix_seconds)
            .expect("mtime seconds");
        let legacy_metadata = CodexTitleMetadata::load_from_roots(std::slice::from_ref(&root));
        let legacy_source_file_fingerprint = source_file_fingerprint_with_context(
            &path,
            metadata.len(),
            modified_unix_seconds,
            CODEX_SNAPSHOT_PARSER_VERSION,
            &legacy_metadata.legacy_sidecar_fingerprint,
        );
        let mut index = ScanIndex {
            files: BTreeMap::from([(
                local_index_key(&path),
                ScanIndexEntry {
                    size_bytes: metadata.len(),
                    modified_unix_seconds,
                    modified_unix_nanos: None,
                    source_file_fingerprint: legacy_source_file_fingerprint,
                    last_snapshot_fingerprint: Some("legacy-snapshot-fingerprint".to_string()),
                    last_upload_body_witness: None,
                    effective_upload_body_witness_revision: 0,
                    scan_identity_version: None,
                    codex_joined_member_set: None,
                    codex_captured_joined_member_set: None,
                    codex_protected_owner: None,
                    codex_applied_tier_receipt: None,
                    codex_applied_tier_receipt_required: false,
                    codex_captured_tier_receipt: None,
                    codex_captured_tier_receipt_required: false,
                    codex_captured_uncommitted: false,
                    codex_counting_v2: false,
                },
            )]),
            ..ScanIndex::default()
        };

        let scan = scan_source_roots(
            SnapshotSource::Codex,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-22T08:02:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("scan");
        assert_eq!(scan.scanned_file_count, 1);
        assert_eq!(scan.snapshots.len(), 1);
        let migrated = index.files.get(&local_index_key(&path)).expect("entry");
        assert_eq!(
            migrated.scan_identity_version.as_deref(),
            Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION)
        );
        assert_ne!(
            migrated.last_snapshot_fingerprint.as_deref(),
            Some("legacy-snapshot-fingerprint")
        );
        assert!(migrated.modified_unix_nanos.is_some());
        assert!(index
            .file_snapshot_fingerprints
            .get(&local_index_key(&path))
            .expect("exact entity set")
            .iter()
            .all(|fingerprint| index.snapshot_activity_at.contains_key(fingerprint)));

        let _ = fs::remove_dir_all(root);
    }

