                "{\"timestamp\":\"2026-05-06T11:04:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":150,\"cached_input_tokens\":60,\"output_tokens\":35},\"model_context_window\":258400}}}\n"
