    #[test]
    fn claude_local_otel_does_not_split_unknown_cache_creation() {
        let path = temp_file("claude-effort-cache-ttl");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-07-12T15:07:58.000Z\",\"sessionId\":\"claude-effort-cache-1\",\"summary\":\"t\"}\n",
                "{\"timestamp\":\"2026-07-12T15:07:58.785Z\",\"sessionId\":\"claude-effort-cache-1\",\"message\":{\"model\":\"claude-opus-4-8\",\"usage\":{\"input_tokens\":2,\"output_tokens\":9,\"cache_creation_input_tokens\":2014,\"cache_creation\":{\"ephemeral_1h_input_tokens\":2014,\"ephemeral_5m_input_tokens\":0}}}}\n"
            ),
        )
        .expect("write fixture");
        let mut items =
            parse_claude_code_jsonl_file(&path, "2026-07-12T15:08:00Z", "fp".to_string())
                .expect("parse");
        let evidence = BTreeMap::from([(
            "claude-effort-cache-1".to_string(),
            vec![crate::claude_local_otel::ClaudeLocalOtelEvidence {
                fingerprint: "legacy-v0.1.77".to_string(),
                session_id: "claude-effort-cache-1".to_string(),
                observed_at: "2026-07-12T15:07:58.852Z".to_string(),
                model: "claude-opus-4-8".to_string(),
                effort: "low".to_string(),
                input_tokens: 2,
                output_tokens: 9,
                // v0.1.77 stored Claude's aggregate cache_creation_tokens in
                // the 5m field even when the transcript proved they were 1h.
                cache_creation_5m_tokens: 2014,
                request_count: 1,
                ..Default::default()
            }],
        )]);

        apply_claude_effort_evidence(&mut items, &evidence);

        let rows = &items[0].usage_buckets[0].model_usage;
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].reasoning_effort, None);
        assert_eq!(rows[0].input_tokens, 2);
        assert_eq!(rows[0].output_tokens, 9);
        assert_eq!(rows[0].request_count, 1);
        assert_eq!(rows[0].cache_creation_5m_tokens, 0);
        assert_eq!(rows[0].cache_creation_1h_tokens, 2014);
        validate_snapshot_item(0, &items[0]).expect("unchanged snapshot remains byte-exact");

        let mut scoped_items =
            parse_claude_code_jsonl_file(&path, "2026-07-12T15:08:00Z", "fp".to_string())
                .expect("parse scoped fixture");
        let scoped_evidence = BTreeMap::from([(
            "claude-effort-cache-1".to_string(),
            vec![crate::claude_local_otel::ClaudeLocalOtelEvidence {
                fingerprint: "explicit-1h".to_string(),
                session_id: "claude-effort-cache-1".to_string(),
                observed_at: "2026-07-12T15:07:58.852Z".to_string(),
                model: "claude-opus-4-8".to_string(),
                effort: "low".to_string(),
                input_tokens: 2,
                output_tokens: 9,
                cache_creation_1h_tokens: 2014,
                request_count: 1,
                ..Default::default()
            }],
        )]);
        apply_claude_effort_evidence(&mut scoped_items, &scoped_evidence);
        let scoped_rows = &scoped_items[0].usage_buckets[0].model_usage;
        assert_eq!(scoped_rows.len(), 1);
        assert_eq!(scoped_rows[0].reasoning_effort, None);
        assert_eq!(scoped_rows[0].cache_creation_1h_tokens, 2014);
        validate_snapshot_item(0, &scoped_items[0])
            .expect("explicit sidecar TTL remains ignored and byte-exact");
        let _ = fs::remove_file(path);
    }

    #[test]
    fn claude_local_otel_account_hash_stamps_unique_and_clears_conflict() {
        let path = temp_file("claude-account-evidence");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-07-31T10:00:00Z\",\"sessionId\":\"claude-account-1\",\"summary\":\"t\"}\n",
                "{\"timestamp\":\"2026-07-31T10:01:00Z\",\"sessionId\":\"claude-account-1\",\"message\":{\"model\":\"claude-opus-5\",\"usage\":{\"input_tokens\":2,\"output_tokens\":1}}}\n"
            ),
        )
        .expect("write fixture");
        let mut items =
            parse_claude_code_jsonl_file(&path, "2026-07-31T10:02:00Z", "fp".to_string())
                .expect("parse");
        let account_a = "a".repeat(64);
        let account_b = "b".repeat(64);
        let unique = BTreeMap::from([(
            "claude-account-1".to_string(),
            vec![crate::claude_local_otel::ClaudeLocalOtelEvidence {
                session_id: "claude-account-1".to_string(),
                model: "unmatched-model".to_string(),
                effort: "high".to_string(),
                input_tokens: 2,
                output_tokens: 1,
                request_count: 1,
                account_identity_checked: true,
                account_identifier_hash: Some(account_a.clone()),
                ..Default::default()
            }],
        )]);

        apply_claude_effort_evidence(&mut items, &unique);

        assert!(items[0]
            .model_usage
            .iter()
            .chain(
                items[0]
                    .usage_buckets
                    .iter()
                    .flat_map(|bucket| bucket.model_usage.iter())
            )
            .all(|row| row.account_identifier_hash.as_deref() == Some(account_a.as_str())));
        let unique_fingerprint = items[0].snapshot_fingerprint.clone();

        let conflicting = BTreeMap::from([(
            "claude-account-1".to_string(),
            vec![
                crate::claude_local_otel::ClaudeLocalOtelEvidence {
                    account_identity_checked: true,
                    account_identifier_hash: Some(account_a),
                    ..Default::default()
                },
                crate::claude_local_otel::ClaudeLocalOtelEvidence {
                    account_identity_checked: true,
                    account_identifier_hash: Some(account_b),
                    ..Default::default()
                },
            ],
        )]);
        apply_claude_effort_evidence(&mut items, &conflicting);

        assert!(items[0]
            .model_usage
            .iter()
            .chain(
                items[0]
                    .usage_buckets
                    .iter()
                    .flat_map(|bucket| bucket.model_usage.iter())
            )
            .all(|row| row.account_identifier_hash.is_none()));
        assert_ne!(items[0].snapshot_fingerprint, unique_fingerprint);

        let partially_identified = BTreeMap::from([(
            "claude-account-1".to_string(),
            vec![
                crate::claude_local_otel::ClaudeLocalOtelEvidence {
                    account_identity_checked: true,
                    account_identifier_hash: Some("a".repeat(64)),
                    ..Default::default()
                },
                crate::claude_local_otel::ClaudeLocalOtelEvidence {
                    account_identity_checked: true,
                    ..Default::default()
                },
            ],
        )]);
        apply_claude_effort_evidence(&mut items, &unique);
        apply_claude_effort_evidence(&mut items, &partially_identified);
        assert!(items[0]
            .model_usage
            .iter()
            .chain(
                items[0]
                    .usage_buckets
                    .iter()
                    .flat_map(|bucket| bucket.model_usage.iter())
            )
            .all(|row| row.account_identifier_hash.is_none()));

        apply_claude_effort_evidence(&mut items, &unique);
        let unidentified = BTreeMap::from([(
            "claude-account-1".to_string(),
            vec![crate::claude_local_otel::ClaudeLocalOtelEvidence {
                account_identity_checked: true,
                ..Default::default()
            }],
        )]);
        apply_claude_effort_evidence(&mut items, &unidentified);
        assert!(items[0]
            .model_usage
            .iter()
            .chain(
                items[0]
                    .usage_buckets
                    .iter()
                    .flat_map(|bucket| bucket.model_usage.iter())
            )
            .all(|row| row.account_identifier_hash.is_none()));

        let mixed_legacy_and_current = BTreeMap::from([(
            "claude-account-1".to_string(),
            vec![
                crate::claude_local_otel::ClaudeLocalOtelEvidence::default(),
                crate::claude_local_otel::ClaudeLocalOtelEvidence {
                    account_identity_checked: true,
                    account_identifier_hash: Some("a".repeat(64)),
                    ..Default::default()
                },
            ],
        )]);
        apply_claude_effort_evidence(&mut items, &mixed_legacy_and_current);
        assert!(items[0]
            .model_usage
            .iter()
            .chain(
                items[0]
                    .usage_buckets
                    .iter()
                    .flat_map(|bucket| bucket.model_usage.iter())
            )
            .all(|row| row.account_identifier_hash.is_none()));

        let incomplete_current = BTreeMap::from([(
            "claude-account-1".to_string(),
            vec![crate::claude_local_otel::ClaudeLocalOtelEvidence {
                account_identity_checked: true,
                account_identifier_hash: Some("a".repeat(64)),
                request_count: 1,
                ..Default::default()
            }],
        )]);
        apply_claude_effort_evidence(&mut items, &incomplete_current);
        assert!(items[0]
            .model_usage
            .iter()
            .chain(
                items[0]
                    .usage_buckets
                    .iter()
                    .flat_map(|bucket| bucket.model_usage.iter())
            )
            .all(|row| row.account_identifier_hash.is_none()));
        let _ = fs::remove_file(path);
    }

    #[test]
    fn claude_account_hash_uses_exact_request_ids_when_auxiliary_requests_share_session() {
        let path = temp_file("claude-account-request-id-coverage");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-08-06T00:00:00Z\",\"type\":\"assistant\",\"sessionId\":\"claude-request-id-1\",\"requestId\":\"req_usage_1\",\"message\":{\"id\":\"msg_1\",\"model\":\"claude-opus-4-8\",\"usage\":{\"input_tokens\":10,\"output_tokens\":2}}}\n",
                "{\"timestamp\":\"2026-08-06T00:01:00Z\",\"type\":\"assistant\",\"sessionId\":\"claude-request-id-1\",\"requestId\":\"req_usage_2\",\"message\":{\"id\":\"msg_2\",\"model\":\"claude-opus-4-8\",\"usage\":{\"input_tokens\":20,\"output_tokens\":3}}}\n"
            ),
        )
        .expect("write fixture");
        let parsed = parse_claude_code_jsonl_file(&path, "2026-08-06T00:02:00Z", "fp".to_string())
            .expect("parse");
        assert_eq!(
            parsed[0].claude_usage_request_ids,
            BTreeSet::from(["req_usage_1".to_string(), "req_usage_2".to_string()])
        );
        assert!(serde_json::to_value(&parsed[0])
            .expect("serialize snapshot")
            .get("claude_usage_request_ids")
            .is_none());
        let account_hash = "a".repeat(64);
        let row = |request_id: &str, input_tokens, output_tokens| {
            crate::claude_local_otel::ClaudeLocalOtelEvidence {
                fingerprint: request_id.to_string(),
                session_id: "claude-request-id-1".to_string(),
                request_id: request_id.to_string(),
                model: "claude-opus-4-8".to_string(),
                input_tokens,
                output_tokens,
                request_count: 1,
                account_identity_checked: true,
                account_identifier_hash: Some(account_hash.clone()),
                ..Default::default()
            }
        };
        let with_prompt_suggestion = BTreeMap::from([(
            "claude-request-id-1".to_string(),
            vec![
                row("req_usage_1", 10, 2),
                row("req_usage_2", 20, 3),
                // Claude Code prompt suggestions use the same root session id
                // but are absent from the billed usage transcript. Their
                // totals intentionally make aggregate coverage impossible.
                row("req_prompt_suggestion", 50_000, 1_000),
            ],
        )]);
        let mut items = parsed.clone();
        apply_claude_effort_evidence(&mut items, &with_prompt_suggestion);
        assert!(items[0]
            .model_usage
            .iter()
            .all(|row| row.account_identifier_hash.as_deref() == Some(account_hash.as_str())));
        assert_eq!(items[0].claude_account_withheld_reason, None);

        // Negative control: one missing billed request must remain unknown even
        // though the sidecar's other rows all name one account. If the new
        // request-id coverage were decorative/always-true, this would fail.
        let incomplete = BTreeMap::from([(
            "claude-request-id-1".to_string(),
            vec![
                row("req_usage_1", 10, 2),
                row("req_prompt_suggestion", 50_000, 1_000),
            ],
        )]);
        let mut incomplete_items = parsed.clone();
        apply_claude_effort_evidence(&mut incomplete_items, &incomplete);
        assert!(incomplete_items[0]
            .model_usage
            .iter()
            .all(|row| row.account_identifier_hash.is_none()));
        assert_eq!(
            incomplete_items[0].claude_account_withheld_reason,
            Some(CLAUDE_ACCOUNT_WITHHELD_INCOMPLETE_REQUEST_EVIDENCE)
        );
        assert!(serde_json::to_value(&incomplete_items[0])
            .expect("serialize snapshot")
            .get("claude_account_withheld_reason")
            .is_none());

        let mut conflicting_rows = with_prompt_suggestion["claude-request-id-1"].clone();
        conflicting_rows[2].account_identifier_hash = Some("b".repeat(64));
        let conflicting = BTreeMap::from([("claude-request-id-1".to_string(), conflicting_rows)]);
        let mut conflicting_items = parsed.clone();
        apply_claude_effort_evidence(&mut conflicting_items, &conflicting);
        assert!(conflicting_items[0]
            .model_usage
            .iter()
            .all(|row| row.account_identifier_hash.is_none()));
        // The second account is only on an auxiliary request outside this
        // entity's billed request ids: withheld, but not "multiple accounts".
        assert_eq!(conflicting_items[0].claude_account_withheld_reason, None);

        let mut owned_mix_rows = with_prompt_suggestion["claude-request-id-1"].clone();
        owned_mix_rows[1].account_identifier_hash = Some("b".repeat(64));
        let owned_mix = BTreeMap::from([("claude-request-id-1".to_string(), owned_mix_rows)]);
        let mut owned_mix_items = parsed;
        apply_claude_effort_evidence(&mut owned_mix_items, &owned_mix);
        assert!(owned_mix_items[0]
            .model_usage
            .iter()
            .all(|row| row.account_identifier_hash.is_none()));
        assert_eq!(
            owned_mix_items[0].claude_account_withheld_reason,
            Some(CLAUDE_ACCOUNT_WITHHELD_MULTIPLE_ACCOUNTS)
        );
        let _ = fs::remove_file(path);
    }

    fn claude_account_family_fixture() -> (PathBuf, String, Vec<SnapshotItem>) {
        static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        let root = temp_dir(&format!(
            "claude-account-family-{}",
            NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
        ));
        let parent = "1338a80a-f36e-4cbc-a5bb-50fc66430ba5".to_string();
        let parent_path = root.join(format!("{parent}.jsonl"));
        fs::write(
            &parent_path,
            concat!(
                "{\"timestamp\":\"2026-08-02T07:00:00Z\",\"type\":\"assistant\",\"sessionId\":\"1338a80a-f36e-4cbc-a5bb-50fc66430ba5\",\"requestId\":\"req_1\",\"message\":{\"model\":\"claude-haiku-4-5\",\"usage\":{\"input_tokens\":10,\"output_tokens\":10}}}\n",
                "{\"timestamp\":\"2026-08-02T07:00:01Z\",\"type\":\"assistant\",\"sessionId\":\"1338a80a-f36e-4cbc-a5bb-50fc66430ba5\",\"requestId\":\"req_2\",\"message\":{\"model\":\"claude-haiku-4-5\",\"usage\":{\"input_tokens\":10,\"output_tokens\":10}}}\n",
                "{\"timestamp\":\"2026-08-02T07:00:02Z\",\"type\":\"assistant\",\"sessionId\":\"1338a80a-f36e-4cbc-a5bb-50fc66430ba5\",\"requestId\":\"req_3\",\"message\":{\"model\":\"claude-haiku-4-5\",\"usage\":{\"input_tokens\":10,\"output_tokens\":10}}}\n",
                "{\"timestamp\":\"2026-08-02T07:00:03Z\",\"type\":\"assistant\",\"sessionId\":\"1338a80a-f36e-4cbc-a5bb-50fc66430ba5\",\"requestId\":\"req_4\",\"message\":{\"model\":\"claude-haiku-4-5\",\"usage\":{\"input_tokens\":10,\"output_tokens\":10}}}\n"
            ),
        )
        .expect("write parent fixture");
        let child_dir = root.join(&parent).join("subagents");
        fs::create_dir_all(&child_dir).expect("create child dir");
        let child_path = child_dir.join("agent-a4d1585d310070d0f.jsonl");
        fs::write(
            &child_path,
            "{\"timestamp\":\"2026-08-02T07:00:04Z\",\"type\":\"assistant\",\"sessionId\":\"1338a80a-f36e-4cbc-a5bb-50fc66430ba5\",\"agentId\":\"a4d1585d310070d0f\",\"isSidechain\":true,\"requestId\":\"req_5\",\"message\":{\"model\":\"claude-haiku-4-5\",\"usage\":{\"input_tokens\":10,\"output_tokens\":1}}}\n",
        )
        .expect("write child fixture");
        let mut items = parse_claude_code_jsonl_file(
            &parent_path,
            "2026-08-02T07:01:00Z",
            "parent-fp".to_string(),
        )
        .expect("parse parent");
        items.extend(
            parse_claude_code_jsonl_file(
                &child_path,
                "2026-08-02T07:01:00Z",
                "child-fp".to_string(),
            )
            .expect("parse child"),
        );
        assert_eq!(items.iter().map(|item| item.request_count).sum::<u64>(), 5);
        assert!(items[1]
            .attribution_facts
            .iter()
            .any(|fact| { fact.field == "parent_session_ref" && fact.value == parent }));
        (root, parent, items)
    }

    fn claude_account_family_evidence(
        parent: &str,
        hashes: &[String],
    ) -> BTreeMap<String, Vec<crate::claude_local_otel::ClaudeLocalOtelEvidence>> {
        let rows = hashes
            .iter()
            .enumerate()
            .map(
                |(index, hash)| crate::claude_local_otel::ClaudeLocalOtelEvidence {
                    fingerprint: format!("family-{index}"),
                    session_id: parent.to_string(),
                    request_id: format!("req_{}", index + 1),
                    observed_at: format!("2026-08-02T07:00:0{index}Z"),
                    model: "claude-haiku-4-5".to_string(),
                    // Deliberately differ from transcript token accounting. The
                    // family fallback is proven by one checked row per request.
                    output_tokens: 11,
                    request_count: 1,
                    account_identity_checked: true,
                    account_identifier_hash: Some(hash.clone()),
                    ..Default::default()
                },
            )
            .collect();
        BTreeMap::from([(parent.to_string(), rows)])
    }

    fn complete_family_proof(
        parent: &str,
        items: &[SnapshotItem],
    ) -> BTreeMap<String, ProvenClaudeAccountFamily> {
        BTreeMap::from([(
            parent.to_string(),
            ProvenClaudeAccountFamily {
                members: items
                    .iter()
                    .map(|item| (item.source_session_id.clone(), item.request_count))
                    .collect(),
                member_request_id_fingerprints: items
                    .iter()
                    .map(|item| {
                        let request_id_hashes = claude_snapshot_request_id_hashes(item)
                            .expect("fixture has one request id per request");
                        (
                            item.source_session_id.clone(),
                            claude_request_id_set_fingerprint(&request_id_hashes),
                        )
                    })
                    .collect(),
            },
        )])
    }

    pub(super) fn complete_api_row(
        parent: &str,
        request_id: &str,
        sequence: u64,
        input_tokens: u64,
        output_tokens: u64,
        cache_creation_tokens: u64,
    ) -> crate::claude_local_otel::ClaudeLocalOtelEvidence {
        let mut row = crate::claude_local_otel::ClaudeLocalOtelEvidence {
            capture_revision: "claude_api_request:v2".to_string(),
            session_id: parent.to_string(),
            request_id: request_id.to_string(),
            client_request_id: format!("client-{request_id}"),
            observed_at: format!("2026-08-02T07:00:{sequence:02}Z"),
            model: "claude-haiku-4-5".to_string(),
            effort: "high".to_string(),
            query_source: "user".to_string(),
            speed: "fast".to_string(),
            cost_usd_micros: Some(100),
            event_sequence: Some(sequence),
            app_version: "2.1.226".to_string(),
            input_tokens,
            output_tokens,
            cache_creation_tokens,
            request_count: 1,
            account_identity_checked: true,
            account_identifier_hash: Some("a".repeat(64)),
            ..Default::default()
        };
        let bytes = serde_json::to_vec(&row).expect("serialize API evidence");
        row.fingerprint = format!("sha256:{:x}", Sha256::digest(bytes));
        row
    }

    pub(super) fn complete_trace_row(
        parent: &str,
        request_id: &str,
        agent_id: &str,
    ) -> crate::claude_local_otel::ClaudeTraceOwnershipEvidence {
        let mut row = crate::claude_local_otel::ClaudeTraceOwnershipEvidence {
            capture_revision: "claude_llm_request_ownership:v1".to_string(),
            session_id: parent.to_string(),
            request_id: request_id.to_string(),
            client_request_id: format!("client-{request_id}"),
            agent_id: agent_id.to_string(),
            observed_at: "2026-08-02T07:00:30Z".to_string(),
            ..Default::default()
        };
        let bytes = serde_json::to_vec(&row).expect("serialize trace evidence");
        row.fingerprint = format!("sha256:{:x}", Sha256::digest(bytes));
        row
    }

    fn cache_split_fixture() -> (PathBuf, String, Vec<SnapshotItem>) {
        let root = temp_dir("claude-cache-split");
        let parent = "1338a80a-f36e-4cbc-a5bb-50fc66430ba5".to_string();
        let path = root.join(format!("{parent}.jsonl"));
        let record = json!({
            "timestamp": "2026-08-02T07:00:01Z", "type": "assistant",
            "sessionId": parent, "requestId": "req_cache_split",
            "message": {"id": "msg_cache_split", "model": "claude-haiku-4-5",
                "usage": {"input_tokens": 10, "output_tokens": 10,
                    "cache_creation_input_tokens": 2014,
                    "cache_creation": {"ephemeral_5m_input_tokens": 2014,
                        "ephemeral_1h_input_tokens": 0}}}
        });
        fs::write(&path, format!("{record}\n")).unwrap();
        let items = parse_claude_code_jsonl_file(
            &path,
            "2026-08-02T07:01:00Z",
            "cache-split-fp".to_string(),
        )
        .unwrap();
        assert_eq!(items.len(), 1);
        (root, parent, items)
    }

    fn cache_split_api_row(
        parent: &str,
        split: bool,
    ) -> crate::claude_local_otel::ClaudeLocalOtelEvidence {
        let mut row = complete_api_row(parent, "req_cache_split", 1, 10, 10, 2014);
        if split {
            row.cache_creation_5m_tokens = 2014;
            row.app_version = "2.1.300".to_string();
        }
        row.fingerprint.clear();
        row.fingerprint = format!(
            "sha256:{:x}",
            Sha256::digest(serde_json::to_vec(&row).unwrap())
        );
        row
    }

    #[test]
    fn claude_cache_split_interpretation_checks_totals_and_counts_rejections() {
        let mut row = crate::claude_local_otel::ClaudeLocalOtelEvidence::default();
        for (total, five_m, one_h, expected) in [
            (2014, 2014, 0, Some((2014, 0, 0))),
            (2014, 0, 2014, Some((0, 2014, 0))),
            (2014, 1000, 1014, Some((1000, 1014, 0))),
            (0, 1000, 1014, Some((1000, 1014, 0))),
            (2014, 0, 0, Some((0, 0, 2014))),
            (0, 0, 0, Some((0, 0, 0))),
            (u64::MAX, 0, 0, Some((0, 0, u64::MAX))),
            (u64::MAX, u64::MAX, 0, Some((u64::MAX, 0, 0))),
            (2013, 1000, 1014, None),
            (2015, 1000, 1014, None),
            (0, u64::MAX, 1, None),
            (u64::MAX, u64::MAX, u64::MAX, None),
        ] {
            row.cache_creation_tokens = total;
            row.cache_creation_5m_tokens = five_m;
            row.cache_creation_1h_tokens = one_h;
            let before = claude_api_cache_creation_rejection_count();
            assert_eq!(claude_api_cache_creation(&row), expected);
            assert_eq!(
                claude_api_cache_creation_rejection_count(),
                before + u64::from(expected.is_none())
            );
        }
    }

