    fn claude_original_carrier_missing_metadata() -> ClaudeTitleMetadata {
        let mut metadata = claude_original_carrier_metadata();
        // Isolate the additive original pair: existing scalar account stays
        // identical to an older durable index that had no organization leaf.
        metadata.original_identity_evidence.clear();
        metadata
    }

    #[test]
    fn claude_original_carrier_actual_parse_preserves_identity_and_usage() {
        let metadata = claude_original_carrier_metadata();
        let complete = claude_original_carrier_fixture(&metadata, "");
        let missing =
            claude_original_carrier_fixture(&claude_original_carrier_missing_metadata(), "");
        let identity = complete.session_account_evidence.as_ref().unwrap();
        assert_eq!(identity.identity_disposition, Some("complete"));
        assert_eq!(
            identity.source_created_at.as_deref(),
            Some("2026-09-30T10:00:00Z")
        );
        assert_eq!(
            (
                complete.input_tokens,
                complete.output_tokens,
                complete.request_count
            ),
            (10, 2, 1)
        );
        assert_eq!(complete.model_usage, missing.model_usage);
        assert_eq!(complete.usage_buckets, missing.usage_buckets);
        assert_eq!(
            snapshot_semantic_component_hashes(SnapshotSource::ClaudeCode, &complete),
            snapshot_semantic_component_hashes(SnapshotSource::ClaudeCode, &missing)
        );
        let wire = serde_json::to_value(&missing).unwrap();
        assert_eq!(
            wire["session_account_evidence"]["identity_disposition"],
            "missing"
        );
        assert!(wire["session_account_evidence"]
            .get("account_identifier_hash")
            .is_none());
        assert!(wire["session_account_evidence"]
            .get("provider_workspace_hash")
            .is_none());
        let partial = claude_original_carrier_fixture(&metadata, "malformed\n");
        assert_eq!(
            partial
                .session_account_evidence
                .unwrap()
                .identity_disposition,
            Some("missing")
        );
        let invalid_fork = format!(
            "{}\n",
            json!({"timestamp":"2026-09-30T09:59:00Z",
            "type":"assistant", "sessionId":"native-session", "forkedFrom":{"sessionId":"parent"},
            "requestId":"unknown-request", "message":{"id":"unknown-message","model":"claude-opus-4-8",
            "usage":{"input_tokens":100,"output_tokens":50}}})
        );
        let semantic_partial = claude_original_carrier_fixture(&metadata, &invalid_fork);
        assert_eq!(
            (
                semantic_partial.input_tokens,
                semantic_partial.output_tokens
            ),
            (10, 2)
        );
        assert_eq!(
            semantic_partial
                .session_account_evidence
                .unwrap()
                .identity_disposition,
            Some("missing")
        );
        let mut incomplete = metadata.clone();
        incomplete.sidecar_census_incomplete = true;
        incomplete.original_identity_census_incomplete = true;
        assert_eq!(
            claude_original_carrier_fixture(&incomplete, "")
                .session_account_evidence
                .unwrap()
                .identity_disposition,
            Some("missing")
        );
        let mut imported = metadata.clone();
        let mut entry = imported
            .original_identity_evidence
            .remove("native-session")
            .unwrap()
            .pop_first()
            .unwrap();
        entry.imported = true;
        imported
            .original_identity_evidence
            .insert("native-session".into(), BTreeSet::from([entry]));
        assert_eq!(
            claude_original_carrier_fixture(&imported, "")
                .session_account_evidence
                .unwrap()
                .identity_disposition,
            Some("missing")
        );
        let mut conflict = metadata;
        let mut other = conflict.original_identity_evidence["native-session"]
            .first()
            .unwrap()
            .clone();
        other.provider_workspace_hash = Some("c".repeat(64));
        conflict
            .original_identity_evidence
            .get_mut("native-session")
            .unwrap()
            .insert(other);
        let identity = claude_original_carrier_fixture(&conflict, "")
            .session_account_evidence
            .unwrap();
        assert_eq!(identity.identity_disposition, Some("conflict"));
        assert_eq!(
            identity.account_identifier_hash,
            ottto_core::billing_identity_hash(
                "anthropic",
                "account",
                "123e4567-e89b-12d3-a456-426614174000"
            )
        );
        assert!(identity.provider_workspace_hash.is_none());
        assert_eq!(
            claude_original_carrier_fixture(&conflict, &invalid_fork)
                .session_account_evidence
                .unwrap()
                .identity_disposition,
            Some("conflict")
        );
    }

    #[test]
    fn claude_original_carrier_healthy_paged_refresh_keeps_completed_identity() {
        let root = temp_dir("claude-original-paged-stability");
        let bucket = root
            .join("123e4567-e89b-12d3-a456-426614174000")
            .join("123e4567-e89b-12d3-a456-426614174001");
        fs::create_dir_all(&bucket).unwrap();
        for number in 0..MAX_CLAUDE_DESKTOP_SESSION_FILES + 1 {
            fs::write(
                bucket.join(format!("{number:05}.json")),
                format!(r#"{{"cliSessionId":"session-{number}"}}"#),
            )
            .unwrap();
        }
        let dirs = BTreeSet::from([root.clone()]);
        let mut index = ScanIndex::default();
        let first = ClaudeTitleMetadata::load_from_store_dirs_with_index(
            &dirs,
            &mut index,
            "2026-09-30T10:00:00Z",
            true,
        );
        assert!(first.original_identity_census_incomplete);
        let complete = ClaudeTitleMetadata::load_from_store_dirs_with_index(
            &dirs,
            &mut index,
            "2026-09-30T10:05:00Z",
            true,
        );
        assert_eq!(
            complete
                .session_account_evidence("session-0")
                .identity_disposition,
            Some("complete")
        );
        let fingerprint = complete.session_sidecar_fingerprint("session-0");
        let mut restored: ScanIndex =
            serde_json::from_slice(&serde_json::to_vec(&index).unwrap()).unwrap();
        for minute in [10, 15, 20, 25] {
            let refreshed = ClaudeTitleMetadata::load_from_store_dirs_with_index(
                &dirs,
                &mut restored,
                &format!("2026-09-30T10:{minute:02}:00Z"),
                true,
            );
            assert_eq!(
                refreshed
                    .session_account_evidence("session-0")
                    .identity_disposition,
                Some("complete")
            );
            assert_eq!(
                refreshed.session_sidecar_fingerprint("session-0"),
                fingerprint
            );
        }
        fs::write(
            bucket.join("00000.json"),
            br#"{"cliSessionId":"changed-session"}"#,
        )
        .unwrap();
        let changed = ClaudeTitleMetadata::load_from_store_dirs_with_index(
            &dirs,
            &mut restored,
            "2026-09-30T10:27:00Z",
            true,
        );
        assert!(
            changed.original_identity_census_incomplete,
            "changed original evidence waits for complete bounded refresh"
        );
        assert_eq!(
            changed
                .session_account_evidence("changed-session")
                .identity_disposition,
            Some("missing")
        );
        let settled = ClaudeTitleMetadata::load_from_store_dirs_with_index(
            &dirs,
            &mut restored,
            "2026-09-30T10:29:00Z",
            true,
        );
        assert_eq!(
            settled
                .session_account_evidence("changed-session")
                .identity_disposition,
            Some("complete")
        );
        // Actual malformed input invalidates the prior completed evaluation;
        // retry backoff cannot accidentally restore it from the durable index.
        fs::write(bucket.join("00000.json"), b"{bad json}").unwrap();
        let lost = ClaudeTitleMetadata::load_from_store_dirs_with_index(
            &dirs,
            &mut restored,
            "2026-09-30T10:30:00Z",
            true,
        );
        assert_eq!(
            lost.session_account_evidence("changed-session")
                .identity_disposition,
            Some("missing")
        );
        let backed_off = ClaudeTitleMetadata::load_from_store_dirs_with_index(
            &dirs,
            &mut restored,
            "2026-09-30T10:30:01Z",
            true,
        );
        assert_eq!(
            backed_off
                .session_account_evidence("changed-session")
                .identity_disposition,
            Some("missing")
        );
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn claude_original_carrier_census_loss_revisits_consumed_transcript_page() {
        let record = |id: &str| {
            json!({"timestamp":"2026-09-30T10:00:00Z", "sessionId":id,
            "message":{"id":id,"model":"claude-opus-4-8","usage":{"input_tokens":5,"output_tokens":2}}}).to_string()
        };
        let (home, first_path, projects) = claude_desktop_fixture(
            "claude-original-loss-revisit",
            "a-session",
            "{}",
            &record("a-session"),
        );
        fs::write(
            first_path.with_file_name("b-session.jsonl"),
            record("b-session"),
        )
        .unwrap();
        let store = home.join("Library/Application Support/Claude/claude-code-sessions");
        fs::remove_dir_all(store.join("account-ctx")).unwrap();
        let bucket = store
            .join("123e4567-e89b-12d3-a456-426614174000")
            .join("123e4567-e89b-12d3-a456-426614174001");
        fs::create_dir_all(&bucket).unwrap();
        for id in ["a-session", "b-session"] {
            fs::write(
                bucket.join(format!("{id}.json")),
                format!(r#"{{"cliSessionId":"{id}","createdAt":"2026-09-30T10:00:00Z"}}"#),
            )
            .unwrap();
        }
        let mut index = ScanIndex::default();
        let first = scan_source_roots_with_limit(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&projects),
            &mut index,
            "2026-09-30T10:05:00Z",
            BACKFILL_WINDOW_DAYS,
            1,
            false,
        )
        .unwrap();
        assert_eq!(first.snapshots.len(), 1);
        let consumed_id = first.snapshots[0].source_session_id.clone();
        assert_eq!(
            first.snapshots[0]
                .session_account_evidence
                .as_ref()
                .unwrap()
                .identity_disposition,
            Some("complete")
        );
        fs::write(bucket.join("a-session.json"), b"{bad json}").unwrap();
        let lost = scan_source_roots_with_limit(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&projects),
            &mut index,
            "2026-09-30T10:06:00Z",
            BACKFILL_WINDOW_DAYS,
            1,
            false,
        )
        .unwrap();
        assert_eq!(lost.snapshots.len(), 1);
        assert_eq!(
            lost.snapshots[0].source_session_id, consumed_id,
            "revisit consumed page, not remaining sibling"
        );
        assert_eq!(
            lost.snapshots[0]
                .session_account_evidence
                .as_ref()
                .unwrap()
                .identity_disposition,
            Some("missing")
        );
        let continued = scan_source_roots_with_limit(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&projects),
            &mut index,
            "2026-09-30T10:06:01Z",
            BACKFILL_WINDOW_DAYS,
            1,
            false,
        )
        .unwrap();
        assert!(
            continued
                .snapshots
                .iter()
                .all(|item| item.source_session_id != consumed_id),
            "persistent failure must not continually reset traversal"
        );
        fs::remove_dir_all(home).unwrap();
    }

    #[test]
    fn claude_original_carrier_creation_never_comes_from_retained_activity() {
        let metadata = claude_original_carrier_metadata();
        for (created, expected) in [
            (Some("2026-09-30T09:00:00Z"), Some("complete")),
            (None, Some("missing")),
            (Some("invalid"), Some("missing")),
            (Some("2026-09-30T10:01:00Z"), Some("missing")),
            (Some("2027-09-30T10:00:00Z"), Some("missing")),
        ] {
            let mut candidate = metadata.clone();
            let mut entry = candidate
                .original_identity_evidence
                .remove("native-session")
                .unwrap()
                .pop_first()
                .unwrap();
            entry.source_created_at = created.map(str::to_string);
            candidate
                .original_identity_evidence
                .insert("native-session".into(), BTreeSet::from([entry]));
            let item = claude_original_carrier_fixture(&candidate, "");
            let evidence = item.session_account_evidence.unwrap();
            assert_eq!(evidence.identity_disposition, expected);
            assert_eq!(
                evidence.source_created_at.as_deref(),
                if expected == Some("complete") {
                    created
                } else {
                    None
                }
            );
            assert_eq!((item.input_tokens, item.output_tokens), (10, 2));
        }
    }

    #[test]
    fn claude_original_carrier_requires_owned_id_and_tracks_census_recovery() {
        let metadata = claude_original_carrier_metadata();
        let root = temp_dir("claude-original-no-owned-id");
        let path = root.join("native-session.jsonl");
        fs::write(&path, json!({"timestamp":"2026-09-30T10:00:00Z", "message":{
            "id":"message", "model":"claude-opus-4-8","usage":{"input_tokens":10,"output_tokens":2}}}).to_string()).unwrap();
        let item = parse_claude_code_jsonl_file_with_title_metadata(
            &path,
            "2026-09-30T10:05:00Z",
            "f".repeat(64),
            &metadata,
            false,
        )
        .unwrap()
        .remove(0);
        assert_eq!(item.source_session_id, "native-session");
        assert_eq!(
            item.session_account_evidence.unwrap().identity_disposition,
            Some("missing")
        );
        let healthy = metadata.session_sidecar_fingerprint("native-session");
        let mut incomplete = metadata;
        incomplete.sidecar_census_incomplete = true;
        incomplete.original_identity_census_incomplete = true;
        let partial = incomplete.session_sidecar_fingerprint("native-session");
        assert_ne!(
            healthy, partial,
            "census recovery must re-evaluate unchanged transcripts"
        );
        incomplete.sidecar_census_incomplete = false;
        incomplete.original_identity_census_incomplete = false;
        assert_eq!(
            healthy,
            incomplete.session_sidecar_fingerprint("native-session")
        );
        let mut candidate = test_candidate(path.clone());
        candidate.source_file_fingerprint = partial;
        let mut index = ScanIndex::default();
        index.record(
            candidate.clone(),
            Some("settled".into()),
            ScanParseOutcome::Snapshot,
        );
        index
            .snapshot_activity_at
            .insert("settled".into(), Some("2026-09-30T10:00:00Z".into()));
        assert_eq!(
            index.candidate_decision(&candidate),
            CandidateDecision::Skip
        );
        candidate.source_file_fingerprint = healthy;
        assert_eq!(
            index.candidate_decision(&candidate),
            CandidateDecision::Parse,
            "actual selection must revisit unchanged transcript after census recovery"
        );
        index.record(
            candidate.clone(),
            Some("settled".into()),
            ScanParseOutcome::Snapshot,
        );
        assert_eq!(
            index.candidate_decision(&candidate),
            CandidateDecision::Skip,
            "recovery converges instead of forcing repeated uploads"
        );
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn claude_original_carrier_source_generated_wire_corpus() {
        let complete = claude_original_carrier_fixture(&claude_original_carrier_metadata(), "");
        assert!(complete
            .tool_usage
            .as_ref()
            .is_some_and(|rows| rows.iter().any(|row| row.name == "Read" && row.count == 1)));
        let mut cases = Vec::new();
        let mut declared_cases = Vec::new();
        for disposition in ["complete", "missing", "conflict"] {
            for cache in [false, true] {
                for curve in [false, true] {
                    let mut item = complete.clone();
                    if disposition == "missing" {
                        item = claude_original_carrier_fixture(
                            &claude_original_carrier_missing_metadata(),
                            "",
                        );
                    } else if disposition == "conflict" {
                        let mut metadata = claude_original_carrier_metadata();
                        let mut other = metadata.original_identity_evidence["native-session"]
                            .first()
                            .unwrap()
                            .clone();
                        other.provider_workspace_hash = Some("c".repeat(64));
                        metadata
                            .original_identity_evidence
                            .get_mut("native-session")
                            .unwrap()
                            .insert(other);
                        item = claude_original_carrier_fixture(&metadata, "");
                    }
                    prepare_cache_observations(&mut item, None);
                    if !cache {
                        item.cache_observations = None;
                        item.cache_observations_state = None;
                    }
                    if !curve {
                        item.context_curve = None;
                    }
                    let source_item = item;
                    for tools in [
                        "omitted",
                        "empty_default_only",
                        "nonempty",
                        "truncated_only",
                    ] {
                        let mut item = source_item.clone();
                        match tools {
                            "omitted" | "truncated_only" => item.tool_usage = None,
                            "empty_default_only" => item.tool_usage = Some(vec![]),
                            _ => {}
                        }
                        item.tool_usage_truncated = tools == "truncated_only";
                        let mut request = valid_v6_batch_request();
                        request.source = "claude_code".into();
                        request.snapshots = vec![item];
                        apply_upload_policy(
                            SnapshotSource::ClaudeCode,
                            &mut request.snapshots,
                            request.upload_policy,
                        );
                        request.snapshots[0].snapshot_fingerprint =
                            snapshot_fingerprint(SnapshotSource::ClaudeCode, &request.snapshots[0]);
                        let item = &request.snapshots[0];
                        assert_eq!(
                            item.session_account_evidence
                                .as_ref()
                                .unwrap()
                                .identity_disposition,
                            Some(disposition)
                        );
                        assert_eq!(snapshot_upload_body_witness_version(item), Some(23));
                        assert_eq!(item.cache_observations.is_some(), cache);
                        assert_eq!(
                            item.session_account_evidence,
                            source_item.session_account_evidence
                        );
                        assert_eq!(
                            (item.input_tokens, item.output_tokens, item.request_count),
                            (
                                source_item.input_tokens,
                                source_item.output_tokens,
                                source_item.request_count
                            )
                        );
                        assert_eq!(item.model_usage, source_item.model_usage);
                        assert_eq!(item.usage_buckets, source_item.usage_buckets);
                        let bytes = serde_json::to_vec(&request).unwrap();
                        let wire: Value = serde_json::from_slice(&bytes).unwrap();
                        let projection = snapshot_upload_body_witness_payload(item);
                        for field in [
                            "session_account_evidence",
                            "context_curve",
                            "tool_usage",
                            "tool_usage_truncated",
                        ] {
                            assert_eq!(
                                projection.get(field),
                                wire["snapshots"][0].get(field),
                                "original Claude declared presence: {field}/{tools}"
                            );
                        }
                        assert_eq!(
                            wire["snapshots"][0].get("tool_usage_truncated"),
                            (tools == "truncated_only").then_some(&Value::Bool(true))
                        );
                        let canonical = crate::canonical_json::canonicalize(&projection).unwrap();
                        let digest = snapshot_upload_body_witness(item);
                        assert_eq!(digest, format!("{:x}", Sha256::digest(&canonical)));
                        let public = if cache { 13 } else { 7 };
                        let response = |version, proof, unchanged| {
                            let reference = crate::snapshot_client::SnapshotEntityRef {
                                source_session_id: item.source_session_id.clone(),
                                snapshot_fingerprint: item.snapshot_fingerprint.clone(),
                                occurrence_count: 1,
                                body_witness_version: version,
                                body_witness_digest: proof,
                                head_etag: item.cache_observations.as_ref().map(|_| "a".repeat(64)),
                                head_challenge: None,
                            };
                            crate::snapshot_client::SnapshotBatchResponse {
                                accepted: 1,
                                sessions_reconciled: 0,
                                session_ids: vec![],
                                disabled: false,
                                disabled_reason: None,
                                entity_ack_contract: Some(SNAPSHOT_ENTITY_ACK_CONTRACT.into()),
                                accepted_entities: if unchanged {
                                    vec![]
                                } else {
                                    vec![reference.clone()]
                                },
                                unchanged_entities: if unchanged {
                                    vec![reference]
                                } else {
                                    vec![]
                                },
                                rejected_entities: vec![],
                                conflict_entities: vec![],
                            }
                        };
                        for unchanged in [false, true] {
                            response(Some(public), Some(digest.clone()), unchanged)
                                .validate_entity_ack(&request)
                                .unwrap();
                            for (version, proof) in [
                                (Some(public), Some("0".repeat(64))),
                                (None, None),
                                (Some(23), Some(digest.clone())),
                                (Some(if cache { 7 } else { 13 }), Some(digest.clone())),
                            ] {
                                assert!(response(version, proof, unchanged)
                                    .validate_entity_ack(&request)
                                    .is_err());
                            }
                        }
                        let case = json!({"disposition":disposition,"cache":cache,"curve":curve,
                        "provenance":"actual Claude transcript parser, original Desktop index and normal HTTP serializer",
                        "wire":wire,
                        "wire_body_utf8":String::from_utf8(bytes).unwrap(),
                        "internal_version":snapshot_upload_body_witness_version(item),
                        "released_ack_version":public,
                        "digest":digest,
                        "body_projection":projection,
                        "cache_observations_state":item.cache_observations_state});
                        if tools == "nonempty" {
                            cases.push(case.clone());
                        }
                        let mut declared_case = case;
                        declared_case["tools"] = json!(tools);
                        declared_case["body_projection_canonical_utf8"] =
                            json!(String::from_utf8(canonical).unwrap());
                        declared_cases.push(declared_case);
                    }
                }
            }
        }
        assert_eq!(cases.len(), 12);
        let bytes = serde_json::to_vec_pretty(
            &json!({"contract_version":"claude_original_wire_corpus:v1", "cases":cases}),
        )
        .unwrap();
        let fixture = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/snapshot-audit/claude-original-source-corpus-v1.json");
        if std::env::var_os("UPDATE_CLAUDE_ORIGINAL_CORPUS").is_some() {
            fs::write(&fixture, &bytes).unwrap();
        }
        assert_eq!(fs::read(&fixture).unwrap(), bytes,
            "regenerate only from the actual Claude source/index/HTTP path with UPDATE_CLAUDE_ORIGINAL_CORPUS=1");
        if let Ok(output) = std::env::var("OTTTO_CLAUDE_ORIGINAL_CORPUS_OUT") {
            fs::write(output, &bytes).unwrap();
        }
        assert_eq!(declared_cases.len(), 48);
        if let Ok(output) = std::env::var("OTTTO_CLAUDE_ORIGINAL_DECLARED_CORPUS_OUT") {
            fs::write(output, serde_json::to_vec_pretty(
                &json!({"contract_version":"claude_original_declared_wire_corpus:v1", "cases":declared_cases})
            ).unwrap()).unwrap();
        }
    }

    #[test]
    fn claude_original_carrier_request_observations_veto_without_creating_identity() {
        use crate::claude_local_otel::{
            ClaudeIdentityAttributeEvidence, ClaudeIdentityAttributeOrigin,
            ClaudeIdentityDisposition, ClaudeLocalOtelEvidence, ClaudeRequestIdentityEvidence,
        };
        let original = claude_original_carrier_fixture(&claude_original_carrier_metadata(), "");
        let observed = |request: &str, org: &str| ClaudeLocalOtelEvidence {
            request_id: request.into(),
            request_identity: Some(ClaudeRequestIdentityEvidence {
                identity_hash_scheme: "provider-sha256:v1".into(),
                account: ClaudeIdentityAttributeEvidence {
                    origin: ClaudeIdentityAttributeOrigin::LogRecord,
                    disposition: ClaudeIdentityDisposition::Complete,
                    resource_hash: None,
                    log_record_hash: ottto_core::billing_identity_hash(
                        "anthropic",
                        "account",
                        "123e4567-e89b-12d3-a456-426614174000",
                    ),
                },
                organization: ClaudeIdentityAttributeEvidence {
                    origin: ClaudeIdentityAttributeOrigin::LogRecord,
                    disposition: ClaudeIdentityDisposition::Complete,
                    resource_hash: None,
                    log_record_hash: Some(org.into()),
                },
                disposition: ClaudeIdentityDisposition::Complete,
            }),
            ..Default::default()
        };
        let mut item = original.clone();
        assert!(!veto_claude_original_identity(
            &mut item,
            &[observed("other-request", &"c".repeat(64))]
        ));
        assert!(!veto_claude_original_identity(
            &mut item,
            &[observed(
                "owned-request",
                &ottto_core::billing_identity_hash(
                    "anthropic",
                    "organization",
                    "123e4567-e89b-12d3-a456-426614174001"
                )
                .unwrap()
            )]
        ));
        assert!(veto_claude_original_identity(
            &mut item,
            &[observed("owned-request", &"c".repeat(64))]
        ));
        assert_eq!(
            item.session_account_evidence
                .as_ref()
                .unwrap()
                .identity_disposition,
            Some("conflict")
        );
        assert_eq!(
            item.session_account_evidence
                .as_ref()
                .unwrap()
                .provider_workspace_hash,
            ottto_core::billing_identity_hash(
                "anthropic",
                "organization",
                "123e4567-e89b-12d3-a456-426614174001"
            )
        );
        assert_eq!(item.model_usage, original.model_usage);
        let mut missing =
            claude_original_carrier_fixture(&claude_original_carrier_missing_metadata(), "");
        assert!(!veto_claude_original_identity(
            &mut missing,
            &[observed(
                "owned-request",
                &ottto_core::billing_identity_hash(
                    "anthropic",
                    "organization",
                    "123e4567-e89b-12d3-a456-426614174001"
                )
                .unwrap()
            )]
        ));
        assert_eq!(
            missing
                .session_account_evidence
                .unwrap()
                .identity_disposition,
            Some("missing")
        );
    }

    #[test]
    fn claude_desktop_original_identity_preserves_full_native_pair() {
        let store = Path::new("native-store");
        let account = "123e4567-e89b-12d3-a456-426614174000";
        let org = "123e4567-e89b-12d3-a456-426614174001";
        let evidence = claude_desktop_original_identity(
            store,
            &store
                .join(account.to_uppercase())
                .join(org)
                .join("native.json"),
        )
        .expect("in-scope native file");
        assert_eq!(
            evidence.account_identifier_hash,
            ottto_core::billing_identity_hash("anthropic", "account", account)
        );
        assert_eq!(
            evidence.provider_workspace_hash,
            ottto_core::billing_identity_hash("anthropic", "organization", org)
        );
        assert!(!evidence.imported);
        let encoded = serde_json::to_string(&evidence).expect("encode evidence");
        assert!(!encoded.contains(account));
        assert!(!encoded.contains(org));
        for (account, org) in [
            ("account-ctx", org),
            (account, "short-org"),
            ("device", "synthetic"),
        ] {
            let incomplete = claude_desktop_original_identity(
                store,
                &store.join(account).join(org).join("native.json"),
            )
            .expect("in-scope incomplete identity");
            assert!(
                incomplete.account_identifier_hash.is_none()
                    || incomplete.provider_workspace_hash.is_none()
            );
        }
        assert!(claude_desktop_original_identity(store, Path::new("other/file.json")).is_none());
    }

    #[test]
    fn claude_desktop_original_identity_retains_import_veto_without_raw_tag() {
        let home = temp_dir("claude-original-import-origin");
        let store = home.join("store");
        let path = store
            .join("123e4567-e89b-12d3-a456-426614174000")
            .join("123e4567-e89b-12d3-a456-426614174001")
            .join("native.json");
        fs::create_dir_all(path.parent().expect("parent")).expect("directories");
        for marker in [
            None,
            Some(serde_json::json!("terminal-cli")),
            Some(serde_json::json!("unknown-sensitive-tag")),
            Some(serde_json::Value::Null),
        ] {
            let mut body = serde_json::json!({"cliSessionId":"native-session", "title":"Title", "titleSource":"auto"});
            if let Some(marker) = &marker {
                body["importedFrom"] = marker.clone();
            }
            fs::write(&path, body.to_string()).expect("write metadata");
            let entry = load_claude_desktop_session_title(
                &path,
                claude_desktop_account_identifier_hash(&store, &path),
                claude_desktop_original_identity(&store, &path),
            )
            .expect("load metadata")
            .expect("entry");
            assert_eq!(
                entry.original_identity.as_ref().expect("identity").imported,
                marker.is_some()
            );
            assert!(entry.account_identifier_hash.is_some());
            assert_eq!(entry.title.as_deref(), Some("Title"));
            let encoded = serde_json::to_string(&entry).expect("encode index entry");
            assert!(!encoded.contains("terminal-cli"));
            assert!(!encoded.contains("unknown-sensitive-tag"));
        }
        fs::remove_dir_all(home).expect("remove fixture");
    }

    #[test]
    fn claude_desktop_original_identity_distinguishes_same_account_org_conflict() {
        let home = temp_dir("claude-original-org-conflict");
        let store = home.join("store");
        let account = "123e4567-e89b-12d3-a456-426614174000";
        let mut index = ScanIndex::default();
        let mut first_fingerprint = None;
        for org in [
            "123e4567-e89b-12d3-a456-426614174001",
            "123e4567-e89b-12d3-a456-426614174002",
        ] {
            let path = store.join(account).join(org).join("native.json");
            fs::create_dir_all(path.parent().expect("parent")).expect("directories");
            fs::write(
                &path,
                r#"{"cliSessionId":"same-session","title":"Title","titleSource":"auto"}"#,
            )
            .expect("metadata");
            let entry = load_claude_desktop_session_title(
                &path,
                claude_desktop_account_identifier_hash(&store, &path),
                claude_desktop_original_identity(&store, &path),
            )
            .expect("load")
            .expect("entry");
            index
                .claude_desktop_title_files
                .insert(local_index_key(&path), entry);
            let metadata = ClaudeTitleMetadata::from_durable_index(&index, false);
            assert!(metadata.account_identifier_hash("same-session").is_some());
            let fingerprint = metadata.session_sidecar_fingerprint("same-session");
            if let Some(first) = &first_fingerprint {
                assert_ne!(&fingerprint, first);
            } else {
                first_fingerprint = Some(fingerprint);
            }
        }
        let encoded = serde_json::to_vec(&index).expect("persist durable index");
        let restored: ScanIndex = serde_json::from_slice(&encoded).expect("restore index");
        let metadata = ClaudeTitleMetadata::from_durable_index(&restored, false);
        assert_eq!(metadata.original_identity_evidence["same-session"].len(), 2);
        assert!(!metadata
            .original_identity_evidence
            .contains_key("unrelated-session"));
        fs::remove_dir_all(home).expect("remove fixture");
    }

    #[test]
    fn claude_desktop_original_identity_legacy_omission_rearms_carrier_without_identity() {
        let entry: ClaudeDesktopTitleIndexEntry = serde_json::from_value(serde_json::json!({
            "cli_session_id":"legacy-session", "title":"Title", "user_set":true,
            "account_identifier_hash":"legacy-account-hash"
        }))
        .expect("read released index entry");
        assert!(entry.original_identity.is_none());
        let mut index = ScanIndex::default();
        index
            .claude_desktop_title_files
            .insert("legacy-path".to_string(), entry);
        let metadata = ClaudeTitleMetadata::from_durable_index(&index, false);
        assert_eq!(
            metadata.session_sidecar_fingerprint("legacy-session"),
            sha256_hex(&[
                "claude_session_sidecar:v2",
                "legacy-session",
                "Title",
                "user",
                "legacy-account-hash",
                "original_session_carrier:v1",
                "",
                "complete"
            ])
        );
        assert!(metadata.original_identity_evidence.is_empty());
    }

    /// A stable canonical transcript UUID for a readable test label; desktop
    /// lineage is exported only for canonical UUIDs.
    fn spawn_cli(label: &str) -> String {
        let hash = sha256_hex(&[label]);
        format!(
            "{}-{}-{}-{}-{}",
            &hash[0..8],
            &hash[8..12],
            &hash[12..16],
            &hash[16..20],
            &hash[20..32]
        )
    }

    fn desktop_spawn_entry_raw(
        cli: &str,
        desktop: &str,
        spawned_from: Option<&str>,
    ) -> ClaudeDesktopTitleIndexEntry {
        ClaudeDesktopTitleIndexEntry {
            cli_session_id: cli.to_string(),
            title: None,
            user_set: false,
            account_identifier_hash: None,
            original_identity: None,
            desktop_session_id: Some(desktop.to_string()),
            spawned_from_desktop_session_id: spawned_from.map(str::to_string),
            spawned_from_unresolved: false,
        }
    }

    fn desktop_spawn_entry(
        label: &str,
        desktop: &str,
        spawned_from: Option<&str>,
    ) -> ClaudeDesktopTitleIndexEntry {
        desktop_spawn_entry_raw(&spawn_cli(label), desktop, spawned_from)
    }

    fn spawn_parent(
        lineage: &BTreeMap<String, ClaudeDesktopSpawnLineage>,
        label: &str,
    ) -> Option<String> {
        lineage
            .get(&spawn_cli(label))
            .map(|lineage| lineage.parent_session_id.clone())
    }

    #[test]
    fn claude_desktop_spawn_lineage_resolves_each_direct_parent() {
        let entries = [
            desktop_spawn_entry("root", "local_root", None),
            desktop_spawn_entry("mid", "local_mid", Some("local_root")),
            desktop_spawn_entry("leaf", "local_leaf", Some("local_mid")),
            // The parent's store file is gone: nothing to resolve the link to.
            desktop_spawn_entry("orphan", "local_orphan", Some("local_missing")),
        ];
        let lineage = claude_desktop_spawn_lineage(entries.iter(), |_| None);

        assert_eq!(spawn_parent(&lineage, "mid"), Some(spawn_cli("root")));
        // Each child names only its direct starting session, never the top.
        assert_eq!(spawn_parent(&lineage, "leaf"), Some(spawn_cli("mid")));
        assert_eq!(spawn_parent(&lineage, "root"), None);
        assert_eq!(spawn_parent(&lineage, "orphan"), None);
        assert_eq!(lineage.len(), 2);
    }

    #[test]
    fn claude_desktop_spawn_lineage_refuses_ambiguous_and_cyclic_links() {
        let entries = [
            // Two store files for one child disagree on who started it.
            desktop_spawn_entry("parent-a", "local_a", None),
            desktop_spawn_entry("parent-b", "local_b", None),
            desktop_spawn_entry("split-child", "local_split_1", Some("local_a")),
            desktop_spawn_entry("split-child", "local_split_2", Some("local_b")),
            // One desktop id claimed by two transcripts.
            desktop_spawn_entry("dup-1", "local_dup", None),
            desktop_spawn_entry("dup-2", "local_dup", None),
            desktop_spawn_entry("dup-child", "local_dup_child", Some("local_dup")),
            // A cycle is not a real edge.
            desktop_spawn_entry("cycle-1", "local_c1", Some("local_c2")),
            desktop_spawn_entry("cycle-2", "local_c2", Some("local_c1")),
            desktop_spawn_entry("self", "local_self", Some("local_self")),
        ];
        let lineage = claude_desktop_spawn_lineage(entries.iter(), |_| None);
        assert!(lineage.is_empty(), "{lineage:?}");
    }

    #[test]
    fn claude_desktop_spawn_lineage_keeps_the_edge_below_an_unresolved_ancestor() {
        let entries = [
            // P names a parent the store cannot resolve: C -> P is still exact.
            desktop_spawn_entry("p-missing", "local_p_missing", Some("local_gone")),
            desktop_spawn_entry("c-missing", "local_c_missing", Some("local_p_missing")),
            // P points at itself.
            desktop_spawn_entry("p-self", "local_p_self", Some("local_p_self")),
            desktop_spawn_entry("c-self", "local_c_self", Some("local_p_self")),
            // P's own files disagree on whether anyone started it.
            desktop_spawn_entry("p-mixed", "local_p_mixed_1", None),
            desktop_spawn_entry("p-mixed", "local_p_mixed_2", Some("local_p_missing")),
            desktop_spawn_entry("c-mixed", "local_c_mixed", Some("local_p_mixed_1")),
            // A cycle above the child, not through it.
            desktop_spawn_entry("x1", "local_x1", Some("local_x2")),
            desktop_spawn_entry("x2", "local_x2", Some("local_x1")),
            desktop_spawn_entry("c-cycle", "local_c_cycle", Some("local_x1")),
        ];
        let lineage = claude_desktop_spawn_lineage(entries.iter(), |_| None);
        for (child, parent) in [
            ("c-missing", "p-missing"),
            ("c-self", "p-self"),
            ("c-mixed", "p-mixed"),
            ("c-cycle", "x1"),
        ] {
            assert_eq!(
                spawn_parent(&lineage, child),
                Some(spawn_cli(parent)),
                "{child}"
            );
        }
        // The cycle members themselves get no edge at all.
        assert_eq!(spawn_parent(&lineage, "x1"), None);
        assert_eq!(spawn_parent(&lineage, "x2"), None);
    }

    #[test]
    fn claude_desktop_spawn_lineage_treats_malformed_spawned_from_as_unknown() {
        let mut malformed = desktop_spawn_entry("p-bad", "local_p_bad", None);
        malformed.spawned_from_unresolved = true;
        let entries = [
            malformed,
            desktop_spawn_entry("c-bad", "local_c_bad", Some("local_p_bad")),
        ];
        let lineage = claude_desktop_spawn_lineage(entries.iter(), |_| None);
        assert_eq!(spawn_parent(&lineage, "c-bad"), Some(spawn_cli("p-bad")));
        assert_eq!(spawn_parent(&lineage, "p-bad"), None);
    }

    #[test]
    fn claude_desktop_spawn_lineage_refuses_cycles_of_any_length() {
        let length = 11;
        let entries = (0..length)
            .map(|position| {
                let parent = format!("local_a{}", (position + 1) % length);
                desktop_spawn_entry(
                    &format!("a{position}"),
                    &format!("local_a{position}"),
                    Some(&parent),
                )
            })
            .collect::<Vec<_>>();
        let lineage = claude_desktop_spawn_lineage(entries.iter(), |_| None);
        assert!(lineage.is_empty(), "{lineage:?}");

        // A long acyclic chain keeps every direct edge.
        let chain = (0..length)
            .map(|position| {
                let parent = (position > 0).then(|| format!("local_b{}", position - 1));
                desktop_spawn_entry(
                    &format!("b{position}"),
                    &format!("local_b{position}"),
                    parent.as_deref(),
                )
            })
            .collect::<Vec<_>>();
        let lineage = claude_desktop_spawn_lineage(chain.iter(), |_| None);
        assert_eq!(lineage.len(), length - 1);
        assert_eq!(spawn_parent(&lineage, "b10"), Some(spawn_cli("b9")));
    }

    #[test]
    fn claude_desktop_spawn_lineage_never_exports_a_non_uuid_transcript_id() {
        let child = spawn_cli("child");
        let mut entries = vec![
            // A path-valued or malformed `cliSessionId` cannot be anyone's parent.
            desktop_spawn_entry_raw("/Users/example/project", "local_path", None),
            desktop_spawn_entry_raw(&child, "local_child", Some("local_path")),
            desktop_spawn_entry_raw("not a session", "local_bad", None),
            desktop_spawn_entry("child-of-bad", "local_child_bad", Some("local_bad")),
            desktop_spawn_entry_raw(
                &spawn_cli("upper").to_ascii_uppercase(),
                "local_upper",
                None,
            ),
            desktop_spawn_entry("child-of-upper", "local_child_upper", Some("local_upper")),
        ];
        // Nor can a non-UUID child carry an edge to a valid parent.
        entries.push(desktop_spawn_entry("valid-parent", "local_valid", None));
        entries.push(desktop_spawn_entry_raw(
            "../escape",
            "local_escape",
            Some("local_valid"),
        ));
        let lineage = claude_desktop_spawn_lineage(entries.iter(), |_| None);
        assert!(lineage.is_empty(), "{lineage:?}");

        // The same shapes with a canonical parent id keep the edge.
        let lineage = claude_desktop_spawn_lineage(
            [
                desktop_spawn_entry("valid-parent", "local_valid", None),
                desktop_spawn_entry_raw(&child, "local_child", Some("local_valid")),
            ]
            .iter(),
            |_| None,
        );
        assert_eq!(
            lineage
                .get(&child)
                .map(|lineage| lineage.parent_session_id.clone()),
            Some(spawn_cli("valid-parent"))
        );
    }

    #[test]
    fn claude_desktop_spawn_lineage_waits_for_a_complete_store_census() {
        let parent = spawn_cli("parent");
        let child = spawn_cli("child");
        let mut index = ScanIndex::default();
        for (key, entry) in [
            (
                "parent",
                desktop_spawn_entry("parent", "local_parent", None),
            ),
            (
                "child",
                desktop_spawn_entry("child", "local_child", Some("local_parent")),
            ),
        ] {
            index
                .claude_desktop_title_files
                .insert(key.to_string(), entry);
        }
        assert!(!index.claude_desktop_lineage_census_complete);
        let partial = ClaudeTitleMetadata::from_durable_index(&index, false);
        assert!(partial.spawn_lineage(&child).is_none());

        index.claude_desktop_lineage_census_complete = true;
        let complete = ClaudeTitleMetadata::from_durable_index(&index, false);
        assert_eq!(
            complete
                .spawn_lineage(&child)
                .map(|lineage| lineage.parent_session_id.as_str()),
            Some(parent.as_str())
        );
    }

    fn desktop_spawn_entry_created(
        label: &str,
        desktop: &str,
        spawned_from: Option<&str>,
        created_at: Option<&str>,
    ) -> ClaudeDesktopTitleIndexEntry {
        let mut entry = desktop_spawn_entry(label, desktop, spawned_from);
        entry.original_identity = Some(ClaudeDesktopIdentityEvidence {
            account_identifier_hash: None,
            provider_workspace_hash: None,
            source_created_at: created_at.map(str::to_string),
            imported: false,
        });
        entry
    }

    fn live_window(first: &str, last: &str) -> ClaudeTranscriptLiveWindow {
        ClaudeTranscriptLiveWindow {
            first_unix_nanos: rfc3339_unix_nanos(first).expect("first"),
            last_unix_nanos: rfc3339_unix_nanos(last).expect("last"),
        }
    }

    /// Resolve with fixed windows per label, recording which transcripts
    /// were asked for.
    fn spawn_lineage_with_windows(
        entries: &[ClaudeDesktopTitleIndexEntry],
        windows: &[(&str, ClaudeTranscriptLiveWindow)],
    ) -> (
        BTreeMap<String, ClaudeDesktopSpawnLineage>,
        BTreeSet<String>,
    ) {
        let windows = windows
            .iter()
            .map(|(label, window)| (spawn_cli(label), *window))
            .collect::<BTreeMap<_, _>>();
        let mut asked = BTreeSet::new();
        let lineage = claude_desktop_spawn_lineage(entries.iter(), |cli| {
            asked.insert(cli.to_string());
            windows.get(cli).copied()
        });
        (lineage, asked)
    }

    #[test]
    fn claude_desktop_spawn_lineage_picks_the_transcript_live_when_the_child_was_created() {
        // One desktop session switched transcripts: old ran 09-09..09-26, new
        // 09-27..09-28. Each store copy names a different `cliSessionId`.
        let entries = [
            desktop_spawn_entry_created("old", "local_owner", None, Some("2026-09-09T18:31:51Z")),
            desktop_spawn_entry_created("new", "local_owner", None, Some("2026-09-09T18:31:51Z")),
            // Created while the old transcript was live, before the switch.
            desktop_spawn_entry_created(
                "before-switch",
                "local_before_1",
                Some("local_owner"),
                Some("2026-09-18T11:29:54.915Z"),
            ),
            desktop_spawn_entry_created(
                "before-switch",
                "local_before_2",
                Some("local_owner"),
                Some("2026-09-18T11:29:54.915Z"),
            ),
            // Created after the switch.
            desktop_spawn_entry_created(
                "after-switch",
                "local_after",
                Some("local_owner"),
                Some("2026-09-28T10:00:00Z"),
            ),
            // Created in the gap between the two: neither was live.
            desktop_spawn_entry_created(
                "in-gap",
                "local_gap",
                Some("local_owner"),
                Some("2026-09-27T02:00:00Z"),
            ),
            // An ordinary single-transcript parent never needs a window.
            desktop_spawn_entry_created("solo", "local_solo", None, None),
            desktop_spawn_entry_created("solo-child", "local_solo_child", Some("local_solo"), None),
        ];
        let (lineage, asked) = spawn_lineage_with_windows(
            &entries,
            &[
                (
                    "old",
                    live_window("2026-09-09T18:31:55.158Z", "2026-09-26T14:31:52.136Z"),
                ),
                (
                    "new",
                    live_window("2026-09-27T18:26:48.551Z", "2026-09-28T15:10:20.064Z"),
                ),
            ],
        );
        assert_eq!(
            spawn_parent(&lineage, "before-switch"),
            Some(spawn_cli("old"))
        );
        assert_eq!(
            spawn_parent(&lineage, "after-switch"),
            Some(spawn_cli("new"))
        );
        assert_eq!(spawn_parent(&lineage, "in-gap"), None);
        assert_eq!(
            spawn_parent(&lineage, "solo-child"),
            Some(spawn_cli("solo"))
        );
        assert_eq!(lineage.len(), 3, "{lineage:?}");
        assert_eq!(asked, BTreeSet::from([spawn_cli("old"), spawn_cli("new")]));
    }

    #[test]
    fn claude_desktop_spawn_lineage_refuses_overlapping_copied_history() {
        // The later transcript copied the earlier one's history, so both start
        // with the same stamps; only the earlier one's last event separates them.
        let windows = [
            (
                "earlier",
                live_window("2026-10-09T14:33:34.213Z", "2026-10-09T20:26:26.825Z"),
            ),
            (
                "forked",
                live_window("2026-10-09T14:33:34.213Z", "2026-10-20T20:09:43.795Z"),
            ),
        ];
        let entries = [
            desktop_spawn_entry_created(
                "earlier",
                "local_fork",
                None,
                Some("2026-10-09T14:33:31Z"),
            ),
            desktop_spawn_entry_created("forked", "local_fork", None, Some("2026-10-09T14:33:31Z")),
            // After the earlier transcript's last event: only the fork was live.
            desktop_spawn_entry_created(
                "after-last",
                "local_after_last",
                Some("local_fork"),
                Some("2026-10-11T12:37:29.831Z"),
            ),
            // Inside the copied span: both windows hold it.
            desktop_spawn_entry_created(
                "inside-copy",
                "local_inside_copy",
                Some("local_fork"),
                Some("2026-10-09T18:00:00Z"),
            ),
            // Within the margin of the earlier transcript's last event.
            desktop_spawn_entry_created(
                "at-boundary",
                "local_at_boundary",
                Some("local_fork"),
                Some("2026-10-09T20:27:00Z"),
            ),
        ];
        let (lineage, _) = spawn_lineage_with_windows(&entries, &windows);
        assert_eq!(
            spawn_parent(&lineage, "after-last"),
            Some(spawn_cli("forked"))
        );
        assert_eq!(spawn_parent(&lineage, "inside-copy"), None);
        assert_eq!(spawn_parent(&lineage, "at-boundary"), None);
        assert_eq!(lineage.len(), 1, "{lineage:?}");
    }

    #[test]
    fn claude_desktop_spawn_lineage_refuses_a_switched_parent_without_evidence() {
        let windows = [
            (
                "old",
                live_window("2026-09-09T18:31:55Z", "2026-09-26T14:31:52Z"),
            ),
            (
                "new",
                live_window("2026-09-27T18:26:48Z", "2026-09-28T15:10:20Z"),
            ),
        ];
        let owner = [
            desktop_spawn_entry_created("old", "local_owner", None, None),
            desktop_spawn_entry_created("new", "local_owner", None, None),
        ];
        let child = |created: &[Option<&str>]| {
            created
                .iter()
                .enumerate()
                .map(|(copy, created_at)| {
                    desktop_spawn_entry_created(
                        "child",
                        &format!("local_child_{copy}"),
                        Some("local_owner"),
                        *created_at,
                    )
                })
                .collect::<Vec<_>>()
        };
        for created in [
            // No creation time at all.
            vec![None],
            // One store copy lacks it.
            vec![Some("2026-09-18T11:29:54Z"), None],
            // Copies disagree.
            vec![Some("2026-09-18T11:29:54Z"), Some("2026-09-28T10:00:00Z")],
            // Unparseable.
            vec![Some("yesterday")],
        ] {
            let entries = owner
                .iter()
                .cloned()
                .chain(child(&created[..]))
                .collect::<Vec<_>>();
            let (lineage, _) = spawn_lineage_with_windows(&entries, &windows);
            assert!(lineage.is_empty(), "{created:?}: {lineage:?}");
        }

        // A dated child still refuses when one candidate transcript is
        // missing, even though the other one is live.
        let entries = owner
            .iter()
            .cloned()
            .chain(child(&[Some("2026-09-18T11:29:54Z")][..]))
            .collect::<Vec<_>>();
        let (lineage, _) = spawn_lineage_with_windows(&entries, &windows[..1]);
        assert!(lineage.is_empty(), "{lineage:?}");
        let (lineage, _) = spawn_lineage_with_windows(&entries, &windows);
        assert_eq!(spawn_parent(&lineage, "child"), Some(spawn_cli("old")));
    }

    #[test]
    fn claude_desktop_spawn_lineage_dates_switched_transcripts_from_the_index() {
        let root = temp_dir("claude-desktop-spawn-by-time");
        let project = root.join("-Users-dev-repo");
        fs::create_dir_all(&project).expect("project dir");
        let line = |stamp: &str| {
            format!("{{\"type\":\"user\",\"timestamp\":\"{stamp}\",\"message\":{{\"timestamp\":\"2001-01-01T00:00:00Z\"}}}}\n")
        };
        // The old transcript is larger than both bounded reads together, and
        // its last line is still being written; nested stamps never count.
        let mut old = String::from("{\"type\":\"custom-title\"}\n");
        old.push_str(&line("2026-09-09T18:31:55Z"));
        let filler = format!(
            "{{\"type\":\"attachment\",\"timestamp\":\"2026-09-12T00:00:00Z\",\"pad\":\"{}\"}}\n",
            "x".repeat(4096)
        );
        while (old.len() as u64) < CLAUDE_TRANSCRIPT_WINDOW_READ_BYTES * 3 {
            old.push_str(&filler);
        }
        old.push_str(&line("2026-09-26T14:31:52Z"));
        old.push_str("{\"type\":\"custom-title\"}\n{\"type\":\"user\",\"timesta");
        let new = format!(
            "{}{}{}",
            line("2026-09-27T19:19:35Z"),
            line("2026-09-27T18:26:48Z"),
            line("2026-09-28T15:10:20Z")
        );
        let mut index = ScanIndex::default();
        for (label, body) in [("old", old), ("new", new)] {
            let path = project.join(format!("{}.jsonl", spawn_cli(label)));
            fs::write(&path, body).expect("write transcript");
            index
                .files
                .insert(local_index_key(&path), manifest_index_entry(None));
        }
        for (key, entry) in [
            (
                "old",
                desktop_spawn_entry_created("old", "local_owner", None, None),
            ),
            (
                "new",
                desktop_spawn_entry_created("new", "local_owner", None, None),
            ),
            (
                "child",
                desktop_spawn_entry_created(
                    "child",
                    "local_child",
                    Some("local_owner"),
                    Some("2026-09-18T11:29:54.915Z"),
                ),
            ),
        ] {
            index
                .claude_desktop_title_files
                .insert(key.to_string(), entry);
        }
        index.claude_desktop_lineage_census_complete = true;

        let old_path = project.join(format!("{}.jsonl", spawn_cli("old")));
        let window = claude_transcript_file_live_window(&old_path).expect("old window");
        assert_eq!(
            window.first_unix_nanos,
            rfc3339_unix_nanos("2026-09-09T18:31:55Z").unwrap()
        );
        assert_eq!(
            window.last_unix_nanos,
            rfc3339_unix_nanos("2026-09-26T14:31:52Z").unwrap()
        );
        let metadata = ClaudeTitleMetadata::from_durable_index(&index, false);
        assert_eq!(
            metadata
                .spawn_lineage(&spawn_cli("child"))
                .map(|lineage| lineage.parent_session_id.clone()),
            Some(spawn_cli("old"))
        );

        // A final record larger than the tail read leaves the end unknown.
        let oversized_tail = project.join("oversized-tail.jsonl");
        fs::write(
            &oversized_tail,
            format!(
                "{}{}{{\"type\":\"user\",\"timestamp\":\"2026-09-30T00:00:00Z\",\"pad\":\"{}\"}}\n",
                line("2026-09-09T18:31:55Z"),
                filler.repeat(64),
                "x".repeat(CLAUDE_TRANSCRIPT_WINDOW_READ_BYTES as usize * 2)
            ),
        )
        .expect("write oversized tail");
        assert_eq!(claude_transcript_file_live_window(&oversized_tail), None);

        // Without the old transcript on disk the child is undatable.
        fs::remove_file(&old_path).expect("remove old transcript");
        let metadata = ClaudeTitleMetadata::from_durable_index(&index, false);
        assert!(metadata.spawn_lineage(&spawn_cli("child")).is_none());
        let _ = fs::remove_dir_all(root);
    }

    fn claude_desktop_spawn_test_transcript(session_id: &str) -> String {
        format!(
            "{{\"timestamp\":\"2026-10-18T10:12:00Z\",\"sessionId\":\"{session_id}\",\"entrypoint\":\"claude-desktop\",\"message\":{{\"model\":\"claude-opus-5-5\",\"usage\":{{\"input_tokens\":35,\"output_tokens\":8}}}}}}\n"
        )
    }

    #[test]
    fn claude_desktop_spawned_session_emits_starting_session_lineage() {
        let parent = "94bd328b-f2a9-4c31-bbfe-e174d41b4310";
        let child = "da1dc804-1c50-4401-8c3c-0898b126772f";
        let (home, transcript_path, projects_root) = claude_desktop_fixture(
            "claude-desktop-spawned",
            child,
            &format!(
                "{{\"sessionId\":\"local_b804dc1e\",\"cliSessionId\":\"{child}\",\"title\":\"UI proposal\",\"titleSource\":\"tool\",\"spawnedFrom\":{{\"sessionId\":\"local_25ffd936\",\"taskId\":\"task_1\",\"sideSession\":true}}}}"
            ),
            &claude_desktop_spawn_test_transcript(child),
        );
        let store_dir = home
            .join("Library")
            .join("Application Support")
            .join("Claude")
            .join("claude-code-sessions")
            .join("account-ctx")
            .join("workspace");
        let unlinked = ClaudeTitleMetadata::load_from_roots(std::slice::from_ref(&projects_root));
        assert!(
            unlinked.spawn_lineage.is_empty(),
            "parent not in the store yet"
        );
        fs::write(
            store_dir.join("local_desktop-0.json"),
            format!(
                "{{\"sessionId\":\"local_25ffd936\",\"cliSessionId\":\"{parent}\",\"title\":\"Repo analysis\",\"spawnedFrom\":null}}"
            ),
        )
        .expect("write parent store file");
        // The parent is its own top-level transcript in the same project.
        let parent_path = transcript_path.with_file_name(format!("{parent}.jsonl"));
        fs::write(&parent_path, claude_desktop_spawn_test_transcript(parent))
            .expect("write parent transcript");
        let metadata = ClaudeTitleMetadata::load_from_roots(std::slice::from_ref(&projects_root));

        // Only the child's sidecar fingerprint moves, so only it re-emits.
        assert_ne!(
            metadata.session_sidecar_fingerprint(child),
            unlinked.session_sidecar_fingerprint(child)
        );
        assert!(metadata.spawn_lineage(parent).is_none());

        let parse = |path: &Path| {
            parse_claude_code_jsonl_file_with_title_metadata(
                path,
                "2026-10-18T10:20:00Z",
                "fp".to_string(),
                &metadata,
                true,
            )
            .expect("parse")
            .into_iter()
            .next()
            .expect("snapshot")
        };
        let item = parse(transcript_path.as_path());
        let parent_item = parse(parent_path.as_path());
        let by_field: BTreeMap<&str, &crate::session_attribution::SessionAttributionFact> = item
            .attribution_facts
            .iter()
            .map(|fact| (fact.field.as_str(), fact))
            .collect();
        // The launch provenance survives as the direct parent edge.
        assert_eq!(by_field["parent_session_ref"].value, parent);
        assert_eq!(by_field["origin_kind"].value, "agent_spawn");
        assert_eq!(by_field["agent_kind"].value, "claude_desktop_session");
        assert_eq!(
            by_field["parent_session_ref"].evidence.kind,
            "provider_artifact"
        );
        assert_eq!(
            by_field["parent_session_ref"].evidence.source_version,
            "claude_desktop_spawn:v1"
        );
        // It never states a Task/Workflow family root or depth.
        assert!(!by_field.contains_key("root_session_ref"));
        assert!(!by_field.contains_key("spawn_depth"));
        assert!(parent_item
            .attribution_facts
            .iter()
            .all(|fact| fact.evidence.source_version != "claude_desktop_spawn:v1"));

        // Both top-level transcripts stay independent usage families, and the
        // fact-derived root agrees with the path-derived complete family.
        assert_eq!(claude_snapshot_family_root(&item), child);
        assert_eq!(claude_snapshot_family_root(&parent_item), parent);
        let mut index = ScanIndex::default();
        for path in [&transcript_path, &parent_path] {
            index
                .files
                .insert(local_index_key(path), manifest_index_entry(None));
        }
        assert_eq!(
            complete_claude_usage_family_members(&index),
            BTreeMap::from([
                (child.to_string(), BTreeSet::from([child.to_string()])),
                (parent.to_string(), BTreeSet::from([parent.to_string()])),
            ])
        );
        fs::remove_dir_all(home).expect("remove fixture");
    }

    #[test]
    fn claude_desktop_spawned_session_with_a_path_cli_session_id_emits_no_lineage() {
        let parent = "94bd328b-f2a9-4c31-bbfe-e174d41b4310";
        let child = "da1dc804-1c50-4401-8c3c-0898b126772f";
        // (child store record, parent store record, link expected). Lineage ids
        // are identities: a path or a whitespace-padded id never links.
        let cases = [
            (
                format!("{{\"sessionId\":\"local_b804dc1e\",\"cliSessionId\":\"{child}\",\"spawnedFrom\":{{\"sessionId\":\"local_parent\"}}}}"),
                format!("{{\"sessionId\":\"local_parent\",\"cliSessionId\":\"{parent}\",\"spawnedFrom\":null}}"),
                true,
            ),
            (
                format!("{{\"sessionId\":\"local_b804dc1e\",\"cliSessionId\":\"{child}\",\"spawnedFrom\":{{\"sessionId\":\"local_parent\"}}}}"),
                "{\"sessionId\":\"local_parent\",\"cliSessionId\":\"/Users/example/project\",\"spawnedFrom\":null}".to_string(),
                false,
            ),
            (
                format!("{{\"sessionId\":\"local_b804dc1e\",\"cliSessionId\":\"{child}\",\"spawnedFrom\":{{\"sessionId\":\"local_parent\"}}}}"),
                format!("{{\"sessionId\":\"local_parent\",\"cliSessionId\":\" {parent} \",\"spawnedFrom\":null}}"),
                false,
            ),
            (
                format!("{{\"sessionId\":\"local_b804dc1e\",\"cliSessionId\":\"{child}\",\"spawnedFrom\":{{\"sessionId\":\" local_parent \"}}}}"),
                format!("{{\"sessionId\":\"local_parent\",\"cliSessionId\":\"{parent}\",\"spawnedFrom\":null}}"),
                false,
            ),
            (
                format!("{{\"sessionId\":\"local_b804dc1e\",\"cliSessionId\":\" {child}\",\"spawnedFrom\":{{\"sessionId\":\"local_parent\"}}}}"),
                format!("{{\"sessionId\":\"local_parent\",\"cliSessionId\":\"{parent}\",\"spawnedFrom\":null}}"),
                false,
            ),
        ];
        for (index, (child_record, parent_record, linked)) in cases.into_iter().enumerate() {
            let (home, transcript_path, projects_root) = claude_desktop_fixture(
                &format!("claude-desktop-spawned-bad-id-{index}"),
                child,
                &child_record,
                &claude_desktop_spawn_test_transcript(child),
            );
            let store_dir = home
                .join("Library")
                .join("Application Support")
                .join("Claude")
                .join("claude-code-sessions")
                .join("account-ctx")
                .join("workspace");
            fs::write(store_dir.join("local_desktop-0.json"), parent_record)
                .expect("write parent store file");
            let metadata =
                ClaudeTitleMetadata::load_from_roots(std::slice::from_ref(&projects_root));
            assert_eq!(
                metadata
                    .spawn_lineage(child)
                    .map(|lineage| lineage.parent_session_id.as_str()),
                linked.then_some(parent),
                "case {index}: {:?}",
                metadata.spawn_lineage
            );
            if !linked {
                assert!(metadata.spawn_lineage.is_empty(), "case {index}");
            }

            let item = parse_claude_code_jsonl_file_with_title_metadata(
                &transcript_path,
                "2026-10-18T10:20:00Z",
                "fp".to_string(),
                &metadata,
                true,
            )
            .expect("parse")
            .into_iter()
            .next()
            .expect("snapshot");
            assert_eq!(
                item.attribution_facts
                    .iter()
                    .any(|fact| fact.evidence.source_version == "claude_desktop_spawn:v1"),
                linked,
                "case {index}"
            );
            assert!(item.attribution_facts.iter().all(|fact| {
                !fact.value.contains("/Users/example") && fact.value.trim() == fact.value
            }));
            assert_eq!(claude_snapshot_family_root(&item), child);
            fs::remove_dir_all(home).expect("remove fixture");
        }
    }

    #[test]
    fn claude_desktop_store_title_applies_to_matching_session() {
        let (home, transcript_path, projects_root) = claude_desktop_fixture(
            "claude-desktop-title",
            "11111111-2222-3333-4444-555555555555",
            "{\"sessionId\":\"local_aaa\",\"cliSessionId\":\"11111111-2222-3333-4444-555555555555\",\"title\":\"Cost report export columns\",\"titleSource\":\"auto\"}",
            "{\"timestamp\":\"2026-07-10T10:01:00Z\",\"sessionId\":\"11111111-2222-3333-4444-555555555555\",\"message\":{\"model\":\"claude-opus-4-8\",\"usage\":{\"input_tokens\":35,\"output_tokens\":8}}}\n",
        );
        let metadata = ClaudeTitleMetadata::load_from_roots(std::slice::from_ref(&projects_root));
        assert_eq!(metadata.titles.len(), 1);

        let item = parse_claude_code_jsonl_file_with_title_metadata(
            &transcript_path,
            "2026-07-10T10:04:00Z",
            "fp".to_string(),
            &metadata,
            true,
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");

        assert_eq!(
            item.session_display_name.as_deref(),
            Some("Cost report export columns")
        );
        assert_eq!(
            item.session_display_name_source.as_deref(),
            Some("desktop_title")
        );
        let expected_hash =
            ottto_core::billing_identity_hash("anthropic", "account", "account-ctx")
                .expect("account hash");
        assert!(item
            .model_usage
            .iter()
            .all(|row| row.account_identifier_hash.as_deref() == Some(expected_hash.as_str())));
        assert!(item.usage_buckets.iter().all(|bucket| bucket
            .model_usage
            .iter()
            .all(|row| row.account_identifier_hash.as_deref() == Some(expected_hash.as_str()))));
        let serialized = serde_json::to_string(&item).expect("serialize snapshot");
        assert!(serialized.contains("account_identifier_hash"));
        assert!(!serialized.contains("account-ctx"));
        let mut without_account = item.clone();
        for row in &mut without_account.model_usage {
            row.account_identifier_hash = None;
        }
        for bucket in &mut without_account.usage_buckets {
            for row in &mut bucket.model_usage {
                row.account_identifier_hash = None;
            }
        }
        let with_account_components =
            snapshot_semantic_component_hashes(SnapshotSource::ClaudeCode, &item);
        let without_account_components =
            snapshot_semantic_component_hashes(SnapshotSource::ClaudeCode, &without_account);
        assert_eq!(
            policy_neutral_component_hashes(&with_account_components),
            policy_neutral_component_hashes(&without_account_components),
            "hash epoch 1 excludes the later account-identity wire field"
        );
        assert_ne!(
            snapshot_fingerprint_from_component_hashes(
                SnapshotSource::ClaudeCode,
                &item.source_session_id,
                &with_account_components,
            ),
            snapshot_fingerprint_from_component_hashes(
                SnapshotSource::ClaudeCode,
                &without_account.source_session_id,
                &without_account_components,
            ),
            "account evidence must escape semantic no-op suppression"
        );

        let _ = fs::remove_dir_all(home);
    }

    #[test]
    fn late_claude_desktop_account_mapping_escapes_semantic_noop_suppression() {
        let session_id = "33333333-4444-5555-6666-777777777777";
        let home = temp_dir("claude-desktop-account-late-mapping");
        let projects_root = home.join(".claude").join("projects");
        let project_dir = projects_root.join("-Users-dev-repo");
        fs::create_dir_all(&project_dir).expect("create project dir");
        fs::write(
            project_dir.join(format!("{session_id}.jsonl")),
            format!(
                "{{\"timestamp\":\"2026-07-31T10:01:00Z\",\"sessionId\":\"{session_id}\",\"message\":{{\"model\":\"claude-opus-4-8\",\"usage\":{{\"input_tokens\":35,\"output_tokens\":8}}}}}}\n"
            ),
        )
        .expect("write transcript");

        let mut index = ScanIndex::default();
        let first = scan_source_roots(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&projects_root),
            &mut index,
            "2026-07-31T10:04:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("first scan");
        assert_eq!(first.snapshots.len(), 1);
        assert!(first.snapshots[0]
            .model_usage
            .iter()
            .all(|row| row.account_identifier_hash.is_none()));

        let store_dir = home
            .join("Library")
            .join("Application Support")
            .join("Claude")
            .join("claude-code-sessions")
            .join("account-late")
            .join("workspace");
        fs::create_dir_all(&store_dir).expect("create Desktop store");
        fs::write(
            store_dir.join("local_desktop-late.json"),
            format!("{{\"cliSessionId\":\"{session_id}\"}}"),
        )
        .expect("write late account mapping");

        let second = scan_source_roots(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&projects_root),
            &mut index,
            "2026-07-31T10:05:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("second scan");
        assert_eq!(second.scanned_file_count, 1);
        assert_eq!(second.semantic_noop_count, 0);
        assert_eq!(second.snapshots.len(), 1);
        let expected_hash =
            ottto_core::billing_identity_hash("anthropic", "account", "account-late")
                .expect("account hash");
        assert!(second.snapshots[0]
            .model_usage
            .iter()
            .all(|row| row.account_identifier_hash.as_deref() == Some(expected_hash.as_str())));

        let settled = scan_source_roots(
            SnapshotSource::ClaudeCode,
            std::slice::from_ref(&projects_root),
            &mut index,
            "2026-07-31T10:06:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("settled scan");
        assert!(settled.snapshots.is_empty());

        let _ = fs::remove_dir_all(home);
    }

